(window.STORIES=window.STORIES||[]).push(...[{"n": 123, "l": "الجزء 97 | احداث السنه الخامسه من الهجرة | إلغاء التبني | نزول آية الحجاب", "u": "https://www.facebook.com/groups/710210019782034/permalink/818789302257438/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#إلغاء_التبني\n#نزول_آية_الحجاب\nقلنا المرة إللي فاتت إن كان في أحداث اجتماعية بتحصل في المدينة وهيكون لها آثار كبيرة،\nمن الأحداث دي إن بعد غزوة الأحزاب على طول نزلت آية تحريم التبني\nقال تعالى في سورة الأحزاب:\n\"وَمَا جَعَلَ أَدْعِيَاءَكُمْ أَبْنَاءَكُمْ ذَلِكُمْ قَوْلُكُمْ بِأَفْوَاهِكُمْ وَاللَّهُ يَقُولُ الْحَقَّ وَهُوَ يَهْدِي السَّبِيلَ ادْعُوهُمْ لآبَائِهِمْ هُوَ أَقْسَطُ عِنْدَ اللَّهِ\"\nيعني أي حد بيدعي إن فلان ابنه وهو ليسه ابنه في الحقيقة فهو ادعاء باطل وخلاص بقى لا يجوز في الإسلام، \nفكده رجع زيد بن محمد لاسمه القديم وبقى اسمه زيد بن حارثة،\nلكن التبني وأحكامه مغروسة في نفوس العرب، \nفكان لازم حدث كبير يلغي العادة دي من جذورها، \nفإيه إللي حصل بقى\nاحنا كنا قلنا إن رسول الله ﷺ زوّج زينب بنت عمته لزيد بن حارثة رضي الله عنه لما كنا بنتكلم عن أحداث السنة الرابعة من الهجرة في الجزء الثامن والثمانون،\nوقلنا إنها مكنتش موافقة أصلا على الزواج من زيد بن حارثة وبعدين وافقت استجابة لأمر رسول الله ﷺ،\nبعد الزواج حصل مشاكل بين زيد وزوجته زينب زي أي مشاكل بتحصل بين أي زوجين.\n☆أحيانا المرأة تكون تقية وعندها دين وكذلك زوجها،\nلكن بتحصل بينهم مشاكل، مش عشان هم وحشين،\nهو بيبقى مثلا بسبب إن مفيش تكافؤ بين الاثنين سواء من الناحية الاجتماعية أو الناحية العقلية، أو غيرها من الأسباب،\nفهم مش بيبقوا فاهمين بعض فبيحصل صِدام في الشخصيات، فمش دايما معنى إن في مشاكل بين الزوجين يبقى هم معندهمش دين أو شخصياتهم سيئة،\nممكن كل واحد فيهم على خلق ودين عالي جدا بس مش مناسبين لبعض،\nزي زينب رضي الله عنها وزي زيد بن حارثة، كل واحد فيهم مكانته عالية جدا في الإسلام لكن هم مش مناسبين لبعض\nلما حصلت مشاكل بين زيد رضي الله عنه وبين زينب رضي الله عنها راح زيد لرسول الله ﷺ يشتكي له منها،\nعلى أساس إنها بنت عمته وهو إللي مزوّجها له، وكان بيعرّض إنه يطلقها،\nفكان رسول الله ﷺ يُصبّره ويهوّن عليه المشاكل ويقول له لا تفارق زوجتك واصبر عليها وكان يذكّره بتقوى الله في أموره بصفة عامة وفي زوجته بصفة خاصة،\nلأن تقوى الله بتشجع الإنسان على الصبر وتحمل الأذى،\nلكن رسول الله ﷺ وهو بينصح زيد كان مخبي حاجة في نفسه، ومش عايز حد يعرفها\nربنا كان أوحى لرسول الله ﷺ إن زيد هيطلق زينب وإن هو هيتزجها من بعده بأمر من الله عز وجل\nوهنا هتيجي المشكلة \nالعرب في الوقت ده كانوا بيعتقدوا إن الابن بالتبني زيه زي الابن من الصُّلب بالضبط\nيعني الابن من الصّلب يرث من أبوه ويتحرم عليه محارمه، وزوجته لا يتزوجها أبوه، \nفالابن بالتبني عندهم ياخد نفس الحكم ده، ودي قاعدة ثابتة عندهم وزيد بن حارثة كان بقاله حوالي عشرين سنة في التبني ويمكن أكثر، \nفتخيلوا بقى إن في وجهة نظر الناس رسول الله ﷺ هيبقى تزوج طليقة ابنه ودي كانت حاجة كبيرة عند العرب\nأيوة نزلت الآية بتحريم التبني لكن لسه الناس مش مستوعبين الموضوع \nفالتطبيق العملي للحكم الشرعي يختلف في قوته وأثره عن الواقع النظري، \nومن حكمة ربنا إنه لما يريد يغير قاعدة غلط راسخة في النفوس بيغيرها بحدث كبير جدا يزلزل المجتمع كله،\nفلما ربنا أخبر رسول الله ﷺ إن هيتزوج زينب طليقة ابنه بالتبني كان الموضوع صعب على رسول الله ﷺ؛ لأنه عِرف إن الناس مش هتسكت وممكن ياخدوها سبب للطعن في الدين أو طعن في رسول الله ﷺ وهو ده إللي هيحصل فعلا\n☆سؤال بقى،\nليه رسول الله ﷺ كان بيقول لزيد بلاش يطلق زوجته مع إنه عارف إنه كده كده هيطلقها سواء عاجلا أو آجلا\nرسول الله ﷺ كان عايز يتأكد إذا كان زيد رضي الله عنه لسه قلبه متعلق بزوجته ولّا لأ، \nفكان بيؤجل موضوع الطلاق لحد ما يبقى خلاص زيد فعلا مش عايز يكمّل ومتأكد من قراره ومفيش أي تردد من ناحيته وإنه فعلا مبقاش له أي رغبة فيها\nمش ساعات الإنسان في ساعة زعل كده بيبقى مش عايز حاجة معينة ولما الزعل بيروح بيبقى خلاص عادي،\nأو مثلا الزوج يطلق زوجته في ساعة غضب أو يندم على الزواج أصلا، لكن لما يرُوق ونَفسه تهدأ يرجع في كلامه\nفرسول الله ﷺ كان عايز زيد يجيب آخره وإنه ياخد قرار الطلاق من غير أي ندم ممكن يحصل بعدين، \nعشان لما يشوف رسول الله ﷺ وهو متزوج من زينب رضي الله عنها ميبقاش في نفسه أي شيء\nوده كان من مراعاة رسول الله ﷺ لمشاعر أصحابه \n☆بس إزاي ربنا يوحي لرسول الله ﷺ بموضوع زي ده ورسول الله ﷺ يُخفيه عن الناس\nهو الوحي ده مكنش وحي لازم يُخبر به الناس، ده كان معلومة غيْبِيّة خاصة برسول الله ﷺ ربنا عرّفه بها وإنها هتحصل وخلاص، وغير مأمور بتبليغها للناس،\nيعني كان الموضوع راجع لرسول الله ﷺ يقول للناس ولّا لأ،\nفلأن الموضوع هيعمل قلق جامد رسول الله ﷺ أخفاه في نفسه لحد ما ييجي وقته،\nووقت ما ربنا يريد إن الناس تعرف، رسول الله ﷺ كان هيعرّفهم وده إللي حصل زي ما هنشوف\n☆سؤال كمان، \nطيب لما ربنا كان يعلم إن زواج زيد من زينب مش هيستمر غير سنة واحدة وبعدين رسول الله ﷺ هيتزوجها، ما كان رسول الله ﷺ تزوجها من الأول وخلاص \nماهو السبب الرئيسي أصلا لزواج رسول الله ﷺ من زينب رضي الله عنها إبطال عادة التبني بطريقة عملية، \nيعني عشان الناس كلها تعرف إن الابن من التبني ملوش نفس أحكام الابن من الصُّلْب، \nفلو تزوجها رسول الله ﷺ من البداية قبل ما يتزوجها زيد، يبقى فين الحكمة من الزواج كده\nفكان لازم زيد يتزوجها الأول عشان الحكمة من الزواج تتم \nحصل الطلاق فعلا بين زيد وزينب رضي الله عنهما، وبعد انتهاء عدّتها خطبها رسول الله ﷺ،\nوهنا المنافقين مسكتوش بقى، وحصل إللي كان رسول الله ﷺ خايف منه، المنافقين قعدوا يقولوا:\nمحمد بينهانا إننا نتزوج من حلائل أبنائنا، ثم يتزوج هو من حليلة ابنه\nبيتكلموا عن الآية إللي في سورة النساء إللي بتقول إن زوجة الابن محرمة على الأب،\n\"حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ .....وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ\"\nلكن هنا في فرق كبير جدا، ربنا بيقول الذين من أصلابكم، وقال على غيرهم أدعيائكم،\nفأنزل الله عز وجل:\n\"مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ\"\nيعني محمد ﷺ مكنش أب لزيد على الحقيقة ولا هو أب لأي حد من الصحابة ولا كانت زينب زوجة ابنه، عشان تقولوا الكلام ده\n☆بس انتم عارفين بقى الناس وكلامهم مبيصدقوا يمسكوا في حاجة ويتكلموا فيها\nفمحدش بيسلَم من كلام الناس حتى رسول الله ﷺ \nنزلت الآيات بقى وضحت كل شيء وأخرست المنافقين والذين في قلوبهم مرض\nتعالوا كده نشوف الآيات وهي بتوصف الموقف إللي حصل بين رسول الله ﷺ وزيد بن حارثة رضي الله عنه:\n\"وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ،\nوَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَن تَخْشَاهُ ۖ \nفَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَاكَهَا لِكَيْ لَا يَكُونَ عَلَى الْمُؤْمِنِينَ حَرَجٌ فِي أَزْوَاجِ أَدْعِيَائِهِمْ إِذَا قَضَوْا مِنْهُنَّ وَطَرًا ۚ وَكَانَ أَمْرُ اللَّهِ مَفْعُولًا\"\nيعني ربنا بيقول لرسول الله ﷺ:\nلما جاءك زيد الذي أنعم الله عليه بالإسلام وأنعمت عليه بالعتق يستشيرك في طلاق زوجته، قلت له لا تفارق زوجتك واصبر، \nوتُخفي في نفسك أن الله أخبرك بأنه سيطلقها وتتزوجها أنت، لأنك خائف من كلام الناس إنهم يقولوا: \nمحمد قال لزيد طلقها عشان يتزوجها هو، وإن محمد تزوج طليقة ابنه،\nلكن كان المفروض إن خوفك يكون من الله فقط؛ لأن خشية الله لا يأتي من ورائها إلا كل خير وهي مانعة لكل شر،\nفلما خلاص زيد مبقاش عايزها ومبقاش في نفسه رغبة من ناحيتها أمرناك بالزواج منها،\nوالزواج ده لفائدة عظيمة وهي إن لما المؤمنين يشوفوك تزوجت من طليقة زيد إللي كان ينتسب إليك ميكونش في صدورهم حرج من الزواج من مطلقات أدعيائهم إللي هم أبناءهم من التبني\nالآيات كان فيها عتاب واضح لرسول الله ﷺ: \nيعني إيه الفائدة إنك تقول لزيد لا تطلقها مع إنك عرفت من الوحي إن الطلاق هيقع هيقع، فكان الأَوْلى أن تصمت وتسيبه يطلقها\nعشان كده الآيات دي كانت شديدة جدا على نفسه ﷺ  لدرجة إن السيدة عائشة قالت:\nلو أن رسول الله ﷺ كان كاتما شيئا من الوحي لكتم هذه الآية:\n\"وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ،\n وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَن تَخْشَاهُ\" \nفالذي تولى تزويج زينب من رسول الله ﷺ هو الله عز وجل، يعني رسول الله ﷺ تزوجها من غير شهود من البشر ولا وليّ ولا مهر ولا عقد،\nحتى إنها كانت تفخر على نساء النبي ﷺ وتقول لهن:\n\" زوَّجكن أهاليكُنَّ، وزوَّجني اللهُ تعالى مِن فوقِ سبعِ سموات\".\n☆فاكرين لما قلت لكم إن زينب رضي الله عنها كانت رفضت الزواج من زيد لأنه مولى يعني عبد سابق وهي كانت ذات شرف وحسب، يعني هي كانت من طبقة راقية وهو لأ،\nوالزواج إللي زي ده كان يُعتبر حاجة كده من الخيال بسبب العادات والتقاليد إللي كان عليها المجتمع العربي قبل الإسلام\nفلما زينب بنت جحش أطاعت أمر رسول الله ﷺ وتنازلت عن نزعة الحَسَب والشرف ربنا عوضها هنا بشرف أعظم تتفاخر بيه بين نساء رسول الله ﷺ \nوهنا نقدر نقول بكل ثقة:\n\"من ترك شيئا لله عوضه الله خيرا منه\" \nوتم الزواج بين زينب بنت جحش وبين رسول الله ﷺ،  وكان عمره ﷺ ساعتها ثمانية وخمسون سنة، أما زينب فكان عمرها ثمانية وثلاثين عام، وكانت هي الزوجة الخامسة لرسول الله ﷺ،\nيبقى زوجات رسول الله ﷺ إللي في عصمته الآن:\nسوْدة بنت زمعة، وعائشة بنت أبي بكر،  وحفصة بنت عمر، وأم سلَمة وزينب بنت جحش \n☆ملحوظة هاااااامة جدا\nالكلام إللي أنا شرحته عن تفسير آية : \n\"وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ\"\n هو ده القول الصحيح الوحيد\nأي رواية تانية غير دي فهي رواية غير صحيحة إطلاقا\nفي روايات بتقول إن رسول الله ﷺ كان رايح يزور زيد بن حارثة لأنه كان مريض، فشاف زينب من وراء الستار فعجبه جمالها فحط وشه في الأرض وقال: \nسبحان مقلب القلوب والأبصار، فزيد قال لرسول الله ﷺ أُطلقها يا رسول عشان تتزوجها، \nفرسول الله ﷺ قال لزيد : لا، فنزلت الآية تقول : وتخفي في نفسك ما الله مبديه،\nيعني انت أخفيت حبك لزينب ورغبتك فيها وقلت لزيد لا ميطلقهاش،\nفغير إن الروايات دي\n غير صحيحة أصلا فهي فيها طعن على رسول الله ﷺ وتقليل من شأنه،\nثم يعني بالعقل\nدي بنت عمته يا جماعة، فمش دي أول مرة هيشوفها يعني فينبهر بجمالها، \nدي اتربت من صغرها قصاده وشافها وهي شابة وهو إللي خطبها لزيد، ومكنش في حجاب ولا حاجة لسه، فعلى أي أساس الروايات الباطلة دي أصلا\nفي يوم زواج السيدة زينب، رسول الله ﷺ دعا الناس عشان ياكلوا، وليمة عرس يعني، \nفأكل جماعة عنده في بيته ﷺ، وبعد ما أكلوا قعدوا يتحدثون، عارفين انتم بعد الأكل الناس بتحب تتكلم مع بعضها وخصوصا لو في يوم فرح\nوالسيدة زينب كانت موجودة في ركن الغرفة وكانت مدياهم ظهرها ووجهها للحائط،\nانتظر رسول الله ﷺ إنهم يقوموا ويمشوا، لم يقوموا،\nهو مش عايز يقول لهم يلّا قوموا امشوا، لأن رسول الله ﷺ كان شديد الحياء،\nفعشان يجيبها بطريقة كويسة من غير ما يحرجهم ﷺ تهيأ للقيام، يعني عمل حركات بحيث إللي حواليه يفهموا إنهم يقوموا، فمحدش قام،\nفقام رسول الله ﷺ وقام معاه بعض الصحابة، واتبقى ثلاثة لسه قاعدين،\nفخرج رسول الله ﷺ من الغرفة، ورجع تاني لقاهم لسه قاعدين وبعد شوية قاموا ومشيوا، فجاءه أنس بن مالك خادمه وقال له إن القوم خلاص مشيوا، فرجع رسول الله ﷺ لبيته ودخل،\nفجاء أنس ليدخل البيت وراء رسول الله ﷺ كعادته فألقى الحجاب بينه وبين أنس، يعني حجب أنس إنه يدخل وراءه البيت وقال له:\nأنزل الله عز وجل:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ \nوَلَٰكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا فَإِذَا طَعِمْتُمْ فَانتَشِرُوا وَلَا مُسْتَأْنِسِينَ لِحَدِيثٍ ۚ \nإِنَّ ذَٰلِكُمْ كَانَ يُؤْذِي النَّبِيَّ فَيَسْتَحْيِي مِنكُمْ ۖ وَاللَّهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ ۚ \nوَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِن وَرَاءِ حِجَابٍ ۚ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ ۚ \nوَمَا كَانَ لَكُمْ أَن تُؤْذُوا رَسُولَ اللَّهِ وَلَا أَن تَنكِحُوا أَزْوَاجَهُ مِن بَعْدِهِ أَبَدًا ۚ إِنَّ ذَٰلِكُمْ كَانَ عِندَ اللَّهِ عَظِيمًا \"\nيعني ربنا بيقول للصحابة:\nمحدش يدخل أي بيت من بيوت النبي إلا لو رسول الله ﷺ نفسه أَذن لكم بالدخول ودعاكم للطعام، \nمش إنكم تتَحيّنون وقت الطعام وتأتوا لرسول الله ﷺ، يعني متجوش لرسول الله ﷺ وانتم عارفين إن ده وقت الأكل بتاعه،\nولو رسول الله ﷺ دعاكم إلى طعام ادخلوا كلوا وامشوا على طول متقعدوش تتكلموا بعد الأكل وتتسامروا،\nلأن كل ده كان بيؤذي النبي والنبي كان بيستحيي منكم ومش بيرضى يقول لكم،\nلكن الله لا يستحيي من الحق، يعني ربنا لن يترك تعليمكم وتأديبكم وبيان الحق حياءا منكم،\nأما زوجات النبي ﷺ إذا كلمتوهم وطلبتم منهن شيء؛  فكلموهن من وراء حجاب، سواء الحجاب ده كان جدار أو أي شيء ساتر بينكم وبينهن؛ لأن ده أبعد عن الريبة والشك وأطهر للقلوب من أي خواطر سيئة فاسدة،\nومينفعش تؤذوا رسول الله ﷺ أبدا؛ لأن مَن يؤذي رسول الله ﷺ ملعونين في الدنيا والآخرة ولهم عذاب أليم،\n\" وَالَّذِينَ يُؤْذُونَ رَسُولَ اللَّهِ لَهُمْ عَذَابٌ أَلِيمٌ \"\n\"إِنَّ الَّذِينَ يُؤْذُونَ اللَّهَ وَرَسُولَهُ لَعَنَهُمُ اللَّهُ فِي الدُّنْيَا وَالْآخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا \"\nأما زوجات النبي فليس لكم أن تتزوجوهن أبدا، محرمات عليكم إلى الأبد سواء بعد موت رسول الله ﷺ أو إذا طلقهن رسول الله ﷺ،\nلأن ده ذنب عظيم جدا لا يعرف مدى عقوبته إلا الله\nوبكده اتفرض الحجاب على زوجات رسول الله ﷺ، ووصل الخبر لعمر بن الخطاب رضي الله عنه فاتبسط بفرض الحجاب على زوجاته ﷺ\nليه بقى\nقبل نزول آية الحجاب كان عمر يقول لرسول الله ﷺ:\nيا رسول الله! يدخل عليك البَرّ والفاجر، فلو إنك تأمر أمهات المؤمنين بالحجاب \nفكان نزول آية الحجاب بعد كلام عمر لرسول الله ﷺ وهي من موافقات عمر لرب العالمين، \nيعني عمر بن الخطاب تكلم بشيء فيه مصلحة فأنزل الله بعدها ما يؤكد كلام عمر رضي الله عنه.\n☆لكن السؤال هنا،\nهو رسول الله ﷺ مكنش عارف الكلام ده، أو هل مثلا عمر رضي الله عنه كان أغْير على نساء رسول الله ﷺ منه ﷺ والعياذ بالله\nرسول الله ﷺ كان عارف كلام عمر وكان أغير الناس،\nلكن رسول الله ﷺ ميقدرش يعمل أي حاجة إلا بوحي؛\nلأنه لا ينطق عن الهوى، فهو كان سايب نسائه على ما جرت عليه عادة العرب إنهم بدون حجاب، \nولو هو حجب نسائه الصحابة هيقلدوه، ويبقى هو كده فرض عليهم حاجة الشرع لسه مجاش بيها،\nورسول الله ﷺ كان حريص دائما إنه لا يَشق على المسلمين بأي أمر مادام الشرع مجاش بيه،\nوخصوصا إن رسول الله ﷺ قال:\n\"أعظَمُ المسلمينَ جُرمًا مَن سأَل عن شيء لم يُحرَّمْ على المسلمينَ، فحُرِّمَ عليهم من أجْلِ مسألتِه\"\nفالأصل في الأمور الإباحة مادام الشرع مقلش عكس كده\nفمادام الوحي لم يأتِ بالحجاب فليه رسول الله ﷺ يلزم نسائه به\nفلما نزلت آية الحجاب خلاص ،كده بقى أمر واجب التنفيذ\n◇طب هو الكلام كده معناه إن الحجاب خاص بزوجات رسول الله ﷺ فقط وباقي النساء لأ\nالموضوع ده محتاج تفصيل كبير، عشان كده هنأجل الإجابة عليه للمرة الجاية إن شاء الله"}, {"n": 124, "l": "الجزء 98 | احداث السنه الخامسه من الهجره | الحجاب في الإسلام", "u": "https://www.facebook.com/groups/710210019782034/permalink/818813782254990/", "t": "الحجاب \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثامنة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#الحجاب_في_الإسلام\nوقفنا المرة إللي فاتت عند سؤال مهم بعد ما اتكلمنا عن نزول آية الحجاب، السؤال كان:\nهل الحجاب خاص بزوجات رسول الله ﷺ فقط وباقي النساء لأ؟\nلكن قبل ما نعرف إجابة السؤال ده، في موقف حصل بين عمر بن الخطاب وبين سوْدة زوجة رسول الله ﷺ،\nبعد نزول آية الحجاب ولبس زوجات رسول الله ﷺ الحجاب الكامل إللي بيغطي وجههم وإيدهم،\nخرجت سوْدة بنت زمعة لقضاء الحاجة، وهم مكنش عندهم حمامات زي عندنا،\nفكانت النساء يخرجن مرة واحدة كل يوم بالليل لقضاء الحاجة، \nوهي خارجة شافها عمر بن الخطاب رضي الله عنه وعرفها لأنها كانت طويلة وجسِيمة يعني جسمها مليان فكان إللي يشوفها يعرفها ،فقال لها:\nإنك والله يا سودة ما تخفين علينا فانظري كيف تخرجين!\nيعني احنا عارفينك حتى لو لابسة الحجاب فمتخرجيش،\nعمر بن الخطاب من غيرته على محارم رسول الله ﷺ مكنش عايز نسائه يخرجن من البيت إطلاقا،\nوعمر كان معروف عنه الغيرة الشديدة \nرجعت سودة وراحت لرسول الله ﷺ وكان في بيت عائشة رضي الله عنها بيتعشى، فقالت له عن إللي قاله لها عمر\nفنزل الوحي في اللحظة دي فقال لها رسول الله ﷺ:\nإن الله قد أَذِنَ لكُنّ أن تخرجُنَ لحاجتكنّ\n☆ عمر بن الخطاب رضي الله عنه كان عايز حتى يحجب شخوص زوجات رسول الله ﷺ، \nيعني حتى هيأتها تكون محجوبة مش مجرد لابسة حجاب يغطيها وبس، للمبالغة لهن في السّتر يعني، لكن ده هيبقى فيه مشقة وضرر عليهن،\nعشان كده ربنا أنزل التخفيف عليهن،\nيبقى حجاب زوجات رسول الله ﷺ دلوقتي هو:\nتغطية كل الجسد حتى الوجه والكفين، وحتى في وقت الشهادة لا يجوز لهن كشف وجوههن ولا في غيرها،\nوفي بعض أقوال العلماء إنهن لا يجوز لهن إظهار شخوصهن يعني هيأتهن إلا لضرورة حتى لو لابسين الحجاب الكامل،\nيعني ميمشوش زينا في الشارع كده وسط الناس\nطبعا إلا لضرورة، زي الحج والعمرة والخروج للخلاء وغيرها من الضرورات،\nولمّا كانت بعض زوجات رسول الله ﷺ بتقعد تحدث الناس بأحاديث رسول الله ﷺ كانت تحدثهم من وراء حجاب، بيكون بينها وبينهم ساتر يعني، \nمكنوش بيقعدوا كده وش لوش ويكلموهن،\nحتى لما زينب بنت جحش زوجة رسول الله ﷺ ماتت بعدين عملوا لها زي قُبة كده عليها وهي متكفنة عشان هيأتها متبنش وهم رايحين يدفنوها،\nوكان الصحابة لا ينظرون إلى زوجات رسول الله ﷺ من بعد نزول آية الحجاب حتى لو كانت أمهات المؤمنين بحجابهن الكامل،\nمتخيلين إن كل ده بين الصحابة وأمهات المؤمنين\n◇نرجع للسؤال بتاعنا، هل الحجاب خاص بزوجات رسول الله ﷺ فقط وباقي النساء لأ\nشوفوا، \nعندنا قاعدة في الدين الإسلامي بتقول:\n\"الأصل في خطابِ الشرع العموم، إلا إذا دلّ الدليلُ على تخصيص ذلك الخِطاب\"\nيعني لما ييجي حكم شرعي مُوجه لشخص معين، ده معناه إن الكلام لكوووول الناس إلا لو الشرع قال باستثناء كذا،\nلما ربنا يقول لرسول الله ﷺ:\n\"يَا أَيُّهَا النَّبِيُّ اتَّقِ اللَّهَ \" \nهل الكلام موجه لرسول الله ﷺ فقط، هل في الكلام دليل إن رسول الله ﷺ هو إللي يتقّ الله فقط،\nلأ...الكلام مُوجه لرسول الله ﷺ ولينا احنا كمان\nهقول لكم مثال من حياتنا العملية يقرب المعنى،\nلما الأم تقول لبنتها: مترميش ورق في الأرض عشان أنا لسه منضفة البيت،\nده معناه إيه؟ هل الكلام مُوجه للبنت بس إنها مترميش ورق في الأرض ولّا مُوجه لكل الموجودين في البيت\nأكيد طبعا لكل الموجودين في البيت، يعني أنا مش همنع بنتي ترمي ورق في الأرض وأنا لسه منضفة وهسمح لغيرها إنه يرمي،\nلأن السبب واحد وهو إن البيت لسه متنضف دلوقتي\nولله المثل الأعلى بقى،\nفلما ربنا يقول عن زوجات رسول الله ﷺ:\n\"وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِن وَرَاءِ حِجَابٍ ۚ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ ۚ\"\nفالكلام عن زوجات رسول الله ﷺ وبرده عن كل نساء الأمة،\nيعني لما الرجل ييجي يطلب من زوجة الرسول ﷺ شيء أو يسألها عن شيء يكون الكلام من وراء حجاب ...من وراء ساتر، \nولما الرجل ييجي يطلب شيء أو يستفسر عن شيء من أي امرأة مش من محارمه يجب إنه يكلمها من وراء حجاب...من وراء ساتر، \nونفس المعنى ده بالضبط كده قوله تعالى:\n\"وَقَرْنَ فِي بُيُوتِكُنَّ\" \n《هنتكلم عنه بالتفصيل بعد شوية إن شاء الله》\nوالسبب في وجود حجاب بين الرجل والمرأة زي ما ربنا قال:\n\"ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ ۚ\"\nوطبعا مفيش أطهر من قلوب الصحابة ولا قلوب زوجات رسول الله ﷺ إللي همّ أمهات المؤمنين ومحرمين عليهم زي أمهاتهم الحقيقيين بالضبط\nفما بالنا بالرجال والنساء من بعدهم، مين أوْلى إنه يكلم النساء من وراء حجاب\nالصحابة إللي ربنا شَهد لهم بأنهم أفضل البشر بعد الأنبياء؟\nولّا الناس العادية إللي أقل منهم في طهارة القلب\nوده كان النوع الأول من الحجاب: حجاب البيت، \nيعني زوجات رسول الله ﷺ والصحابيات وأي امرأة مسلمة هتيجي بعدهن،\nلما حد ييجي البيت ويطلب حاجة أو يستفسر عن حاجة الكلام يكون من وراء ساتر..سواء كان ستارة أو باب، أي حاجة ساترة بين الاتنين.\nطيب وخارج البيت المرأة هيبقى وضعها إيه\nربنا أنزل آية تانية توضح وضع المرأة خارج البيت تلبس إيه، سواء زوجات رسول الله ﷺ أو بناته أو نساء المؤمنين بصفة عامة، قال تعالى:\n\"يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَابِيبِهِنَّ ۚ ذَٰلِكَ أَدْنَىٰ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ  \"\nيعني ربنا بيأمر رسول الله ﷺ إنه يأمر زوجاته وبناته ونساء المؤمنين بأنهن يغطين ويسترن وجوههن وجميع أجسادهن ويغطين الزينة عن الرجال من غير المحارم، عن طريق لبس الجلباب،\nوالجلباب ده عبارة عن عباءة تلبسها المرأة من رأسها وتنزل على باقي الجسم تغطيه كله، وده تعريف الجلباب في لسان العرب، والقرآن نزل بإيه\nنزل بلسان عربي مبين، واخدين بالكم\nوالتغطية دي عشان محدش يتعرض لهن بأذى؛ لأن كان في ناس من المنافقين والفُسّاق بيتعرضوا لزوجات رسول الله ﷺ وللمؤمنات بالأذى لما كانوا بيخرجوا لقضاء الحاجة في الليل، يعني زي كده لما بتشوفوا بعض الشباب بيقعدوا يعاكسوا النساء، \nفلما الصحابة كلموهم، قالوا احنا بنعمل كده للإماء منقصدش\nفنزلت آية الحجاب لزوجات رسول الله ﷺ ونساء المؤمنين، فحصل التفرقة بين الحرة وبين الأَمة.\n☆طبعا هنا سؤال مهم جدا\nهو ليه التفريق بين الأَمة والحُرة في الحجاب أصلا، هي الأمة دي مش امرأة لا يجوز إيذاؤها زيها زي الحرة\nالأصل في الحجاب إنه للحرائر، لكن الإماء ومِلك اليمين لا يتشبهن بالحرائر في الحجاب الكامل،\nفالأَمة في عصر رسول الله ﷺ كان المُتعارف عليه وكان حاجة عادية إنهن مُمْتهنات للخدمة وده الغالب عليهن، ومكنش في منهن خطر من ناحية الجمال، شكلهم مكنش حلو يعني فمكنش في فتنة منهن،\nفلما تكون الأَمة دَميمة الخِلْقة حكمها هيكون زي المرأة العجوز الكبيرة في السن التي لا يجب عليها الحجاب لأنها من القواعد من النساء،\nلكن لو الأََمة جميلة وفيها فتنة أو إذا كَثُر أهل الفساد، فحكمها زي المرأة الحرة بالضبط وتلبس الحجاب الكامل ويجب غض البصر عنها\nوفرض الحجاب على الإماء كان هيبقى في مشقة كبيرة جدا عليهن.\nيا جماعة متخيلين واحدة بتغسل هدوم على إيدها معندهاش غسالة، وتروح تعجن وتخبز، وتحلب الأغنام،\nوتنظف البيت وتطبخ قصاد النار مش بوتاجاز وتولع فرن وكل ده في عز الحر، مفيش حتى مراوح ودي داخلة طالعة وفي شغل طول اليوم\nفلأن النفوس أصلا لا تتطلع لهن وغالبهن لم يكن فيهن جمال،\nفربنا وضع عنهن الحجاب شفقة بهن، فيجوز كشف رأسها ويديها ووجها،\nعارفين،\nابن كثير بيقول في تفسير آية :\n\"ذَٰلِكَ أَدْنَىٰ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ\"\n\"أي إذا فعلنَ ذلكَ عُرِفْن أنهنّ حرائر، لسْنَ بإماءٍ ولا عَوَاهِر\"\nيعني لما المرأة تلبس الجلباب يتعرف عنها إنها حرة مش أَمة ولا عاهرة، \nمتخيلين المأساة إللي احنا وصلنا لها في عصرنا \nشوفوا بقى مع كل ده، فمفيش دليل من القرآن والسنة على إباحة النظر إلى عامة الإِماء، يعني مفيش حاجة بتقول إنه يجوز للرجل إنه ينظر للإماء، ولا في دليل إنهن يتركن الحجاب، ويُظهرن زينتهن،\nالفرق بس إن القرآن لم يأمرهن بنفس إللي أمر به الحرائر،\nهو أه في تفريق، بس زي ما قلنا التفريق عشان ميكونش عليهم مشقة، أما لو في فتنة فحكمهن زي الحرائر\nوكان عمر الخطاب بيضرب الأمة إذا احتجبت زي الحرة ويُسقط عنها الحجاب، لأنها تشبهت بالحرائر،\nوطبعا ده فيه مفسدة تانية،\nوهي إن أخلاق الإماء كانت مختلفة عن أخلاق الحرائر،\nفتخيلوا لو الأمة لبست الحجاب الكامل وعملت حاجات سيئة، \nهتبقى شُبهَة لكل واحدة لابسة الحجاب الكامل من الحرائر، لكن زي ما قلنا إذا مكنش فيهن فتنة\nحتى شيخ الإسلام بن تيمية كان على عصره إماء تُركيات، فكان يُفتي بإنهن يلبسن الحجاب الكامل بسبب الفتنة إللي حصلت بسببهن\nكان يقول إن الإماء على عهد الصحابة كانوا بيمشوا في الطرقات عادي متكشفات الرؤوس، ويخدمن الرجال ومحدش في قلبه شيء، \nلكن لو تركنا الإماء التركيات الجميلات يمشين بدون حجاب هيبقى باب فساد عظيم\nنرجع بقى لرسول الله ﷺ،\nرسول الله ﷺ بلّغ زوجاته وبناته وقرأ الآية على الصحابة والصحابة راحوا بلغوا الآيات لنسائهن،\nزوجات رسول الله ﷺ وبناته لبسوا الحجاب الكامل إللي يغطي كامل جسدهن خلاص،\nالصحابيات عملوا إيه بقى\nنساء الأنصار خرجن للصلاة خلف رسول الله ﷺ لابسين ملابس سوداء نازلة من الرأس للقدم كأن على رؤوسهن الغربان من السكينة،\nكلهن فهِمن الآية بنفس المعنى، ولبسن نفس اللون، \nوصلّين خلف رسول الله ﷺ ورآهن رسول الله ﷺ ولم يُنكر على أي واحدة فيهن إنها مثلا فهمت الآية غلط أو طلب منهن إنهن يُغيرن الملابس إللي لابسينها لأن مش هي الملابس المقصودة سواء في الشكل أو في اللون\n☆للتنبيه\nاحنا بنتكلم في السيرة النبوية، يعني أحداث حياة رسول الله ﷺ مع الصحابة والصحابيات،\nفأنا بوصف لكم فهمهم لآيات القرآن وتطبقيها كان إزاي وإقرار رسول الله ﷺ لأفعالهم أو اعتراضه عليها، \nمليش دعوة بأي أقوال مخالفة لكلام رسول الله ﷺ أو فعل الصحابيات؛\nلأن قول رسول الله ﷺ وتطبيق الصحابة لكلامه واقراره وموافقته ﷺ على فهمهم وتطبقيهم هو الأصل\n◇طيب احنا اتكلمنا عن لبس الصحابيات وهم خارجين من بيوتهن، طيب إيه موضوع وقرن في بيوتكن\nآية وقرن في بيوتكن هي في الأصل مُوجهة لزوجات رسول الله ﷺ، وبالتالي موجهة لنساء المسلمين بصفة عامة لأن مفيش دليل بيقول عكس كده، زي ما شرحنا في البداية \nفالأصل إن المرأة تقعد في البيت وتحرص إنها متخرجش من البيت إلا لضرورة حسب حاجتها وكل واحد أدرى بحاله وإيه الضروري بالنسبة له\nولما تخرج من البيت خروجها يكون بضوابط معينة،\nزي مثلا إنها متختلطش بالرجال، \nورسول الله ﷺ نفسه كان حريص إنه يباعد بين الرجال والنساء حتى في المسجد وفي الطريق\nيعني كان الرجال لما يصلوا يكونوا هم في مقدمة المسجد والنساء في آخره، \nوكان ﷺ بعد ما يسلم من الصلاة يستنى شوية والرجال معاه عشان النساء تمشي الأول وميحصلش اختلاط بين الرجال والنساء بعد الصلاة وهم ماشيين،\nحتى يوم العيد كانت النساء بتصلي في ناحية والرجال في ناحية،\nوبعد الصلاة كان رسول الله ﷺ يخطب في الرجال خطبة العيد لوحدهم، وبعدين يروح للنساء يخطب عندهم خطبة تانية لهم،\nوقال رسول الله ﷺ للنساء لما اختلطوا بالرجال في الطريق:\n\"اسْتَأْخِرْنَ، فَإِنَّهُ لَيْسَ لَكُنَّ أَنْ تَحْقُقْنَ الطَّرِيقَ ، عَلَيْكُنَّ بِحَافَّاتِ الطَّرِيقِ،\nفَكَانَتْ الْمَرْأَةُ تَلْتَصِقُ بِالْجِدَارِ حَتَّى إِنَّ ثَوْبَهَا لَيَتَعَلَّقُ بِالْجِدَارِ مِنْ لُصُوقِهَا بِهِ\"\nوقال: \" ليس للنساء وسَط الطريق\"\nيعني المرأة لما تكون ماشية في الشارع 《متتعمدش》 تمشي في وسط الطريق، لكن تمشي في جنب بعيد عن الزحمة؛ لأن وسط الطريق هو الغالب على الرجل إنه بيمشي فيه،\nفلو المرأة مشيت في وسط الطريق وخصوصا لو في زحمة هتخبط في الرايح والجاي، وده لا يجوز\nوطبعا متعملش أي حركة مُتعمدة ولا تضرب برجلها الأرض عشان تبين الزينة المخفية تحت ملابسها،\nلأن المرأة في الجاهلية كان لها طريقة حياة مختلفة عن المرأة في الإسلام،\nالمرأة في الجاهلية كانت بتمشي وسط الرجال حاطة على شعرها حاجة زي الخمار صغير ومرجعاه للوراء ،انتم أكيد شوفتم ما يُسمى بحجاب الراهبات، وإزاي إنه راجع لوراء الكتف كده صح\nأهه ده قريب من لبس النساء أيام الجاهلية، وكانت النساء ساعات تظهر ضفائر شعرها والحلَق بتاعها من القماشة دي، \nوطبعا رقبتها ظاهرة وصدرها باين، وتمشي كده وسط الرجال،\nفجاء القرآن وأمر النساء بوضع جلابيبهن بصورة يغطين بها أجسادهن كاملة زي ما قلنا من شوية،\nوالمرأة في الجاهلية كانت لما تمشي وفي رجلها خلخال صامت فتقوم تضرب الأرض برجلها عشان يعمل صوت وتلفت الرجال إليها لما يسمعوا صوت رنة الخلخال،\nفنهى الله النساء المؤمنات إنهم يعملوا زي النساء في الجاهلية،\nويدخل في النهي ده لو المرأة عملت أي حركة مُتعمدة عشان تبين الزينة إللي مش ظاهرة،\nيعني لابسة سلسلة...لابسة خاتم...لابسة عباية مطرزة من فوق والخمار مغطي كل ده،\nفتقوم عاملة أي حركة وهي متعمّدة عشان تظهر الزينة دي للرجال فده لا يجوز وحكمها زي حكم إللي بتضرب برجلها في الأرض كده\nرسول الله ﷺ كان حريص جدا إنه يفصل الرجال عن النساء ويبعدهم عنهم وكان دائما يحذرهم من النساء،\nقال:\n\"إِيَّاكُمْ وَالدُّخُولَ عَلَى النِّسَاءِ\"\nوالدخول هنا معناه:\n◇إن الرجل يقعد مع المرأة من غير محارمه بغير حجاب شرعي أو يبقى في خُلوة بينهم، يعني يقعدوا مع بعض لوحدهم.\n◇ولو المرأة بحجاب شرعي مينفعش الرجل يقعد معاها لوحدهم لو هو مش من محارمها.\n\"لا يخلُوَن رجل بامرأة ، فإن الشيطان ثالثهما\"\n◇ولو المرأة بحجاب شرعي ومش لوحدها مينفعش الرجل يقعد معاها لو هتحصل فتنة بينهم.\n◇ولو المرأة بحجاب شرعي مينفعش تبقى لوحدها مع مجموعة من الرجال من غير ما يكون معاها محرم.\n◇ولو المرأة بحجاب شرعي مينفعش تقعد مع رجل لوحدها إلا لو معاها محرم.\n\"لاَ يَخْلونَّ رَجُلٌ بِامْرَأةٍ إِلاَّ وَمَعَها ذُو مَحْرَم\"\n☆طب لو مفيش مَحرم للمرأة، تعمل إيه لو《اضطرت》 لموقف هتكون فيه مع رجل لوحدها \nتشوف امرأة تثق فيها تكون معاها وبكده مش هيبقى في خلوة، لكن الرجل إللي هيكونوا معاه ده يكون مأمون الجانب ميتخفش منه إنه يغلب المرأتين على أنفسهما\n☆طيب وأقارب الزوج\nلما رسول الله ﷺ قال إياكم والدخول على النساء، واحد من الصحابة قال له: أرأيت الحَمْو؟\nقال له رسول الله ﷺ: الحَمْوُ الموت\nيعني رسول الله ﷺ بيقول أكثر ناس تخاف منهم هم أقارب الزوج، \nوتتوقع الفتنة والشر من ناحيتهم أكثر لأنه يقدر يوصل للمرأة أكثر من الرجل الأجنبي من غير ما حد يُنكر عليه،\nيعني مش بتسمعوا إللي بيقول عادي إقلعي النقاب قصاد أخو زوجك ده زي أخوكِ، \nحتى الزوج نفسه ساعات بيتخانق ويرفض إن زوجته تلبس نقاب عشان اخواته، أو يشترط عليها إنها لو لبسته تقلعه قصاد اخواته الرجال أو أقاربه،\nفعادة الناس إنهم بيتساهلوا في موضوع أقارب الزوج وتلاقوا الرجل يقعد مع زوجة أخوه لوحدهم عادي ومحدش ينكر عليهم، بعكس لو واحد من الشارع جه ودخل مش هيسمحوا بكده\nفرسول الله ﷺ جعل أقارب الزوج من غير المحارم زي الموت كده، الواحد يحترس منهم لأن الشر والفتنة منهم أقرب\nوطبعا احنا بنسمع وبنشوف بلاوي بسبب تهاون الرجال والنساء في الإلتزام بأوامر ربنا\n◇طيب مين هم دول بالضبط\nأي حد من أقارب الزوج من غير المحارم بالنسبة للمرأة يبقى مينفعش تقعد معاهم وتهزر وتكشف حجابها، ويكون بينهم خلوة\nقعادها معاهم يكون وسط الأهل وبحجاب شرعي كامل وميكنش قعدتهم على سماع أغاني ولا معاصي ولا القعدة نفسها تكون فيها فتنة لأي أحد من الموجودين،\nمحارم الزوج بالنسبة للمرأة بقى هم:\nأبو الزوج وجده لأمه أو أبيه سواء من النسب أو الرضاع، وأبناء الزوج، يعني لو له أبناء من زوجة تانية سواء من النسب أو من الرضاع،\nغير كده يبقوا مش من محارم الزوجة \n☆طيب هو ليه التضييق على النساء كده، يعني هم سبب البلاوي إللي بتحصل دي مثلا\nهنعرف إجابة السؤال ده المرة الجاية إن شاء الله"}, {"n": 125, "l": "الجزء 99 | احداث السنه الخامسه من الهجره | لماذا النساء", "u": "https://www.facebook.com/groups/710210019782034/permalink/818816132254755/", "t": "قصة حقيقيه ل عروسه توفت ليلة زواجها + البنات الي بينزلو صورهم ع الفيس و.. ع مواقع التواصل الاجتماعي سواء محجبات او مختمرات او منتقبات \n عندكو ذنوب جاريه وهتتحملو دا لوحدكم اللهم قد بلغت اللهم فاشهد \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة_والتسعون\n#أحداث_السنة_الخامسة_من_الهجرة\n#لماذا_النساء\nاتكلمنا المرة إللي فاتت عن الحجاب في الإسلام وعن وضع المرأة لمّا تخرج من البيت تبقى لابسة إيه وتمشي إزاي،\nوشوفنا تحذير رسول الله ﷺ من الدخول على النساء، \nوفي أحاديث تانية لرسول الله ﷺ وهو بيحذر الصحابة وبيحذر الرجال مِن بَعدِهم من النساء،\nقال :\n\" المرأةُ عورةٌ ، وإنها إذا خرجت من بيتِها استشرفها الشيطانُ ، و إنها لا تكون أقربَ إلى اللهِ منها في قَعْرِ بيتِها\"\nيعني يجب تغطية المرأة زي ما بنغطي العورة كده، ومحدش يشوفها من غير المحارم، فهي يجب أن تُحفظ وتُصان،\nومش معنى الكلام إن المراة دي حاجة وحشة ونستعر منها زي ما الناس فاهمة،\nأو زي ما كارهي الإسلام بيقولوا\nمثال عملي عشان نقرب المعنى\nالدواء، مش بيبقى مكتوب عليه يُحفظ بعيدا عن أيدي الأطفال، هو الدواء ده حاجة وحشة عشان نخليه بعيد عن الأطفال\nلأ مش حاجة وحشة، لكن لو الأطفال شافوا الدواء وفتحوه وشربوه هيضرهم،\nوكذلك السكّينة، بنبعدها خااالص عن الأطفال عشان لو شافوها وقدروا يوصلوا لها هتضرهم وتؤذيهم،\nفالسكينة نفسها مش وحشة ومنقدرش نستغنى عنها، لكن وجودها مع الشخص الغلط هو إللي مُضر\nكذلك المرأة،\nالمرأة مش حاجة سيئة عشان كده لازم نخبيها\nالمرأة بنبعدها وبنخفيها عن الأشخاص الغلط إللي هيسيؤوا لها أو يُسيؤوا استخدامها،\nومن الأشخاص دول الشيطان، قاعد لها بالمرصاد مستنيها تخرج، وأول ما تخرج من بيتها بيزينها في نظر الرجال فيوقعهم هم الاتنين في الفتنة،\nويا سلام بقى لو مكنتش لابسة الحجاب الشرعي وماشية كاسية عارية ومتزينة بكامل زينتها، تخيلوا كمية المصائب إللي ممكن تحصل\nوالمرأة أقرب ما تكون إلى الله وهي في قعر بيتها،\nشايفين الوصف، بيقول قعر البيت...يعني جوة أوي في العمق،\nوبكده هتاخد أعظم أجر وثواب، والحديث ده بيشجع المرأة إنها متخرجش إلا لضرورة \n☆وطبعا ده يشمل تنزيل المرأة صورها على مواقع التواصل، زي الفيس وغيره\nماهو إزاي في قعر بيتها وهي منزلة صورها الرايح والجاي يشوفها، \nدي سيئات جارية مش طاعة أبدا ،والكلام ده حتى لو لابسة نقاب يا جماعة لأن الأصل في النساء الستر\nثم المرأة مش هتنزل صورتها غير لو شايفة إن شكلها حلو، ودي مصيبة تانية وسيئات جارية أكيد،\nوإلا الطبيعي لما الواحد بيتصور صورة وحشة فهو بيخفيها أصلا مش بيبقى عايز حد يشوفها\nالموضوع ده خطير جدا والله لأن الواحدة ممكن تموت في أي لحظة ويفضل عداد السيئات شغال\nفيا أي حد بيقرأ كلامي سواء رجل أو امرأة راجعوا حساباتكم وشوفوا لو عندكم أي سيئات جارية في أي مكان امسحوها وتوبوا قبل فوات الأوان، محدش يعرف ميعاد موته امتى\n◇ وبمناسبة إن محدش يعرف ميعاد موته هحكي لكم قصة  حصلت معايا ،كان في بنت جارتنا كانت بريئة جدا وكنت بحبها من وهي صغيرة بسبب برائتها دي، وكنت بشوفها بتروح تحفظ قرآن في المسجد،\nانتقلوا للسكن في مكان تاني، وشوفتها بعد كده مرة واحدة قدرًا كده بعد كم سنة لما كبرت شوية، ومشفهتهاش تاني من بعدها وعدت سنين،\nفي يوم كنت راجعة من مشوار بعد المغرب فلقيت عربية متزينة واقفة تحت عمارة فيها كوافير فعرفت إن في عروسة، وأنا معدية من جنب العربية لقيت العروسة جوة العربية وكانت بكامل زينتها، فستان فرح مبين جسمها وكانت فاتحة الشباك عشان الحر وماسكة مروحة بتهوي بيها على نفسها، فكانوا ساعتها بيستعدوا للزفة، \nشوفت العروسة وطلعت البنت جارتنا إللي مشفتهاش بقالي سنين،\nفحزنت جدا؛ لأن من الطبيعي إن الإنسان يحزن لما يشوف حد بيحبه واقع في معاصي، فدعيت لها وأنا ماشية وكنت خايفة عليها بصراحة لتموت لا قدّر الله قبل ما تتوب،\nالعروسة دي هي وزوجها ماتوا بعد الموقف ده بحوالي ثلاثة أو أربع ساعات بعد ما رجعوا بيتهم بعد الفرح بسبب سخان الغاز\nالموضوع كان صدمة لكل المنطقة وصدمة لي أنا شخصيا، لأني كنت لسه شايفاها قبلها على طول وكنت كمان خايفة عليها،\nتعتقدوا لو كانت تعرف إنها على ميعاد مع ملك الموت بعد شوية كان ده بقى حالها، ولّا كانت هتفضل تصلي وتستغفر وتفضل ساجدة لله عشان تموت على طاعة،\nبدل ما كان يتكتب في آخر أعمالها كمية المعاصي والذنوب دي، على فكرة كان عمرها عشرين سنة فقط\nربنا يرحمها ويتجاوز عنها وعنّا ويرزقنا حسن الخاتمة،\nوفي قصص وعبر تانية كتير  بتحصل حوالينا بس احنا إللي مش بناخد بالنا،\nالسعيد من وُعظ بغيره يا جماعة\nنرجع لحديث تاني لرسول الله ﷺ بيحذّر فيها من فتنة النساء قوله:\n\" إنّ الدنيا حُلْوة خَضِرة، وإن الله مستخلِفَكم فيها فينظر كيف تعملون،\nفاتقوا الدنيا واتقوا النساء، فإن أول فتنة بني إسرائيل كانت في النساء\"\nيعني رسول الله ﷺ بيقول عن الدنيا إنها حلوة بسبب إللي فيها من الملذات، \nوالنفس البشرية بيجذبها ويستهويها الطعم الحلو، وكمان النفس بتحب اللون الأخضر، \nمش احنا بنكون مبسوطين لما بنقعد في مكان فيه زرع وأشجار لونهم أخضر،\nفتخيلوا لما نقعد في مكان مُبهِج كده وكمان ناكل أكل طعمه حلو، فهي دي الدنيا حُلوة خَضرة\nربنا جعلنا في الدنيا دي عشان نشوف هنعمل إيه، هل هتبقى هي أكبر همنا ويغلب علينا الطمع ويقتل بعضنا بعض من أجلها، ونصرف أوقاتنا كلها على الدنيا،\nولا هنتقي الله ونأخذ منها ما يعيننا على طاعة الله؟\nوهو ده إللي يقصده رسول الله ﷺ لما قال اتقوا الدنيا،\nيعني خافوا من الدنيا وإنها تشغلكم عن عبادة الله، خذوا منها إللي يكفيكم بدون إفراط ولا تفريط، ومن الدنيا دي أكتر حاجة تخافوا منها وتبعدوا عنها النساء\n\"زُيِّنَ لِلنَّاسِ حُبُّ الشَّهَوَاتِ مِنَ النِّسَاءِ \"\nوقال رسول الله ﷺ: \n\"مَا تَرَكْتُ بَعْدِي فِتْنَةً أَضَرَّ عَلَى الرِّجَالِ مِنْ النِّسَاءِ\"\nوبداية الفساد في بني اسرائيل كان في النساء، كان الأغنياء بينفقوا أموالهم على المظاهر، ملابس وحُلِي والأكل، وأموال كثيرة جدا بتتصرف على الزواج،\nفامرأة الفقير لما كانت تشوف امرأة الغني بتصرف وتجيب، قالت اشمعنى أنا، \nوراحت لزوجها الفقير وبقت تكلفه يصرف عليها ويشتري لها الملابس والأكل والحُلي زي ما الغني بيعمل مع زوجته بالضبط، \n《ركزوا كده في واقعنا وانتم هتشوفوا إن ده إللي بيحصل بالضبط\n》\nفلما زوجة الفقير قعدت تضغط على زوجها إنه يوفر لها التكاليف الباهظة دي، بقى يشتغل ليل نهار عشان يوفر التكاليف دي، ومن هنا بدأت المأساة\nعايز فلوس وشغله مش مكفي يقوم يستدين بالربا فالدين بتاعه يزيد وميقدرش يسدده أو يبيع أرضه أو بيته\nفانشغل بنو إسرائيل في ملاهي الدنيا بسبب المظاهر إللي بتكلف أموال كثيرة وضاع بينهم الدين،\nومن المظاهر إللي النساء في بني اسرائيل اهتموا بها إن امرأة من بني اسرائيل كانت قصيرة، ومكنش عاجبها حالها، وكانت بتضايق لما كانت تمشي بين امرأتين طويلتين،\n فبدل ما ترضى بقضاء الله وميكونش همها الدنيا والمظاهر الخادعة، راحت دوّرت على طريقة تطوّل بيها نفسها فاتخذت رجلين من الخشب، \nحاجة كده زي الجزمة أم كعب عالي، وعملت لنفسها خاتم مُجوّف، فاضي من جوة وحطت جواه مِسك، \nفكانت لما تمشي مع المرأتين محدش يعرفها ولما كانت تعدي على الرجال تفتح الخاتم وتنفضه فيطلع منه ريحة تلفت نظر الرجال إليهن، وكانت تتعمد جذب نظر الرجال إليه،\nلدرجة إن مرة أرسلوا وراءها رجل عشان يعرف هي مين فمعرفش يوصل لها، \nوطبعا واضح إن ملامحها مكنتش باينة لأنها كانت مغطية وشها؛ لأن الحجاب كان موجود في الشرائع السابقة أصلا\n◇كل الكلام ده هياخدنا للسؤال إللي قلناه في آخر الجزء إللي فات: ليه التضييق على النساء كده؟ وهل هم سبب كل البلاوي إللي بتحصل دي مثلا\nخلينا قبل ما نجاوب نشوف مثال بسيط من الحياة، \nلو واحد راح يشتري آيفون بعشرة ولا خمسة عشر ألف جنيه، وفتح العلبة ولقى كُتيبات إرشادية، كتالوج يعني بيقول له افعل ولا تفعل،\nخد بالك من كذا وحافظ على كذا، أنا ممكن أروح للشركة وأقول لهم ليه كل التعقيدات دي\nولّا هيقول هم إللي مصنعينه وهم أدرى بصناعتهم وهلتزم بالتعليمات دي وخلاص، عشان يحافظ على التليفون إللي دفع فيه دم قلبه\nطيب تخيلوا كده واحد جه قال له، سيبك من الكتالوج ده واعمل إللي هقول لك عليه، وقعد يقنعه بكلامه وإن كلامه هو الصح، مع إني ممكن أكون عارف إنه مبيفهمش حاجة خالص \nلو سمع كلامه ومستعملش الكتالوج والتليفون باظ مين إللي يتحمل الغلط؟\nهو ولّا الشركة ولّا الشخص إللي جه عرض مساعدته\nطبعا هو\nالشركة أعطته كتالوج وقالت إنه لازم يتبع التعليمات بالضبط وحذرته إنه لو معملش كده التليفون هيبوظ،\nوهو إللي مسمعش كلام الشركة،\nوالشخص إللي جه عرض عليه مساعدته ده مضربوش على إيده وقال له اسمع كلامي غصب عنك،\nده هو إللي وافق بكامل إرادته إنه يسمع كلامه عشان هو عايز كده،\nسواء بقى عشان يريّح دماغه وميتعبش في اتباع التعليمات،\nأو عشان لو حصل حاجة يحمل التاني المسؤولية أو...أو...\nولله المثل الأعلى في السماوات والأرض، هو مين إللي خلقنا؟ مش ربنا؟!\nهو وضع لنا منهج معين نمشي عليه؛ لأن هو أعلم إيه المناسب للخلق إللي خلقه:\n\"أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ\"\nوحذرنا إن إللي هيعمل عكس المنهج ده حياته هتبوظ وهتبقى ضنك، فييجي بقى شياطين الإنس والجن يقولوا لا لا المنهج ده غلط وإيه التعقيدات والتشدد ده\nوانتم عايزين تدفنوا النساء بالحيا، وإيه عورة دي هي المرأة حاجة بتستعروا منها عشان تغطوها،\nوانتم بتسلبوا حريتها في إنها تقرر شؤون حياتها متخلوها تسافر وتقعد مع رجالة لوحدها، دي بمائة راجل،\nولّا انتم مش واثقين فيها، أيوة بقى قولوا إنكم مش واثقين فيها يا أعداء التحضر والمدنية...إلى آخره من الكلام إللي يوجع البطن\n\"وَيُرِيدُ الَّذِينَ يَتَّبِعُونَ الشَّهَوَاتِ أَنْ تَمِيلُوا مَيْلا عَظِيمً\"\nاحنا بقى كبشر عشان المنهج بتاع ربنا مش عاجبنا ومش على هوانا فبنسيبه ونمشي وراء كلام شياطين الإنس والجن، والنتيجة إيه \nالحياة باظت زي ما ربنا حذرنا\nانتشر جدا الحب والعشق المحرم والاغتصاب والزنا والانتحار والقتل ده غير الأطفال المولودين من الزنا، ومعاصي ملهاش أول من آخر،\nوالمنظومة كلها باظت، حطينا البنزين جنب النار فحصل الانفجار\nربنا خلق الرجل يميل للمرأة ومجرد ما يشوف المرأة دماغه تلف، وخلق المرأة تميل للرجل ومجرد ما يقول لها كلمتين حلوين خلاص بقت تحت رحمته، \nوربنا جعل بينهم الميل ده عشان الحياة البشرية تستمر على الأرض عن طريق الزواج الشرعي، \nولأن ربنا إللي خلقنا يعلم ضعف الرجال والنساء لما بيكونوا قريبين من بعض عمل لنا حدود معينة منعديهاش عشان ميحصلناش ضرر،\nزي ما قلنا مثال السكّينة من شوية، منقدرش نستغنى عنها فلازم إللي يستخدمها يستخدمها صح وإلا هتضره\nكذلك الرجل ضعيف أمام النساء، هو خلقته كده، فلازم نبعد النساء عن الرجال حتى رسول الله ﷺ نفسه قال:\n\"مَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَذْهَبَ لِلُبِّ الرَّجُلِ الحَازِمِ مِنْكُن\"\nيعني مش أي رجل ، ده الرجل الحازم إللي الناس تعمل له ألف حساب، المرأة تاكل بعقله حلاوة من شدة تأثيرها عليه\nيبقى حاجة خطيرة للدرجة دي ينفع نسيبها كده ومناخدش احتياطاتنا\nطبعا لأ، عشان كده ربنا وضع قوانين محددة للنساء عشان متفتنش الرجال وفي نفس الوقت متعرضش نفسها للخطر؛\nلأن في رجال معندهمش دين ولا أخلاق لو حس بس إن المرأة إديته مجال ولو بكلمة حتى من غير ما تقصد هيؤذيها وممكن يفتنها هي كمان\nوللأسف مهما ينصح الناصحون محدش بيسمع، بيرجعوا ويندموا ويقولوا كان معاكم حق بعد ما الكارثة تحصل،\nوانتم شايفين الواقع عامل إزاي، \nوالمصايب إللي كل يوم بنسمعها ونشوفها، وما خفِيَ كان أعظم ومحدش بيتعظ،\nللأسف من أهم عيوب التفكير الإنساني إنه مستعد يسيب الأرقام والإحصائيات والأدلة العقلية والطبية والدينية عشان مجموعة قصص محدودة لا تُقارن بملايين القصص المخالفة لها، وكل واحد بيجري وراء أمل كذاب ويقول أنا غير\n☆هل ده معناه بقى إن المرأة هي سبب كل البلاوي\nشوفوا،\nالمرأة بتكون سبب البلاوي لما تتعدى الحدود إللي ربنا وضعها لها،\nوالرجل بيكون سبب البلاوي لما بيتعدى الحدود إللي ربنا وضعها له \nلا المرأة بتتحاسب ولا بتشيل الغلط عشان هي امرأة ولا الرجل يتحاسب ولا هيشيل الغلط عشان هو رجل،\nربنا بيحاسب على الفعل نفسه يا جماعة مش على مين عمل الفعل\nلو كانت هي السبب في فتنة رجل سواء بقول أو فعل أو ملابس، أو أي شيء فهي هتتحمل ذنب فتنته،\nغير كده مش فهي ملهاش أي ذنب في حاجة\n☆وبما إننا بنتكلم عن النساء، ففي سؤال محير نساء كتير وهو:\nاشمعنى النساء إللي دايما بيتقال عنهم إنهن الفساق وأكثر أهل النار، \nوإنهن لا يصبرن ولا يشكرن ، مع إن في رجال فيهم الصفات دي، والرجال بيعملوا ذنوب أكبر من كده زي القتل والظلم وإثارة الحروب\nبراحة كده وواحدة واحدة\nقال رسول الله ﷺ: \" إِنَّ الْفُسَّاقَ هُمْ أَهْلُ النَّارِ \"\n قِيلَ: يَا رَسُولَ اللهِ، وَمَنِ الْفُسَّاقُ؟\n قَالَ: 《النِّسَاءُ 》\n قَالَ رَجُلٌ : يَا رَسُولَ اللهِ، أَوَلَسْنَ أُمَّهَاتِنَا، وَأَخَوَاتِنَا، وَأَزْوَاجَنَا؟ قَالَ: \"بَلَى، وَلَكِنَّهُنّ إِذَا أُعْطِينَ لَمْ يَشْكُرْنَ، وَإِذَا ابْتُلِينَ لَمْ يَصْبِرْنَ \"\nمش المقصود من الحديث ذم عموم النساء، لكن المقصود التحذير من الفعل ده ومعرفة جزاء إللي هيعمل كده يوم القيامة عشان العاقل ياخد باله وميقعش في الغلط ده\nلكن لو مثلا إذا أُعطي رجل ولم يشكر، وإذا حصل له بلاء ولم يصبر، مش هيبقى حكمه زي النساء؟!\nهيبقى نفس الحكم طبعا؛ لأن زي ما قلنا من شوية ربنا مش بيحاسب على مين عمل الفعل لكن بيحاسب على الفعل نفسه\nلكن تخصيص النساء بالكلام؛ لأن الأخلاق دي غالبة عليهن، والأخلاق دي أقل في الرجال، فرسول الله ﷺ لما اتكلم عن الوعيد كان بيتكلم عن الأغلبية،\nحتى في حديث تاني بيوضح المعنى ده، رسول الله ﷺ بيقول فيه: \"إِنَّ التُّجَّارَ هُمُ الْفُجَّارُ\"\nفقَالَ رَجُلٌ: يَا نَبِيَّ اللهِ أَلَمْ يُحِلَّ اللهُ الْبَيْعَ؟ \nقَالَ: \"إِنَّهُمْ يَقُولُونَ فَيَكْذِبُونَ، وَيَحْلِفُونَ وَيَأْثَمُونَ \"\nفالذم هنا مش لعموم التجار والصحابة نفسهم كان فيهم تجار، لكن هو بيقول إن الغالب على جنس التجار الفجور والكذب، فبيحذر التجار من الفعل ده عشان يحرصوا على البر في البيع والشراء،\nوالنساء أكثر أهل النار زي ما رسول الله ﷺ قال:\n\"يَا مَعْشَرَ النِّسَاءِ، تَصَدَّقْنَ وَأَكْثِرْنَ الِاسْتِغْفَارَ، فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ \"\n فَقَالَتِ امْرَأَةٌ مِنْهُنَّ : وَمَا لَنَا يَا رَسُولَ اللهِ أَكْثَرُ أَهْلِ النَّارِ؟\n قَالَ: \"تُكْثِرْنَ اللَّعْنَ، وَتَكْفُرْنَ الْعَشِيرَ \"\nفهو ده الغالب عليهن، كُفران العشير واتباع الهوى والميل إلى عاجل زينة الحياة الدنيا، فتضعف المرأة عن عمل الآخرة والاستعداد لها،\nواستجابة المرأة للي بيدعوها للآخرة وأعمالها بتبقى صعبة، بعكس لو حد دعاها إلى زينة الدنيا بتنخدع بسهولة وتستجيب بسرعة\nوخدوا بالكم إن لو الرجل برده كفَر العشير وأكثر اللعن زي النساء برده هيبقى نفس مصيرهن بالضبط\nبس الحديث هنا زي ما قلنا بيتكلم عن الأغلبية، وقلنا برده من شوية إن ربنا بيحاسب على الفعل، مش مين عمل الفعل\nأما موضوع إن الرجال بيعملوا أكثر من كده من إشعال حروب وقتل وظلم، فاللي يعمل كده ربنا هيعاقبه بالعقاب إللي يستحقه وذكره في القرآن أو السنة\nلكن ده ملوش علاقة بالأحاديث بتاعة النساء، \nوالجرائم والمعاصي إللي الرجل بيعملها دي جزاؤها مش أقل من جزاء النساء،\nلكن الأحاديث بتتكلم عن 《الأكثرية》 مش عن《الشّديّة》،\nيعني كفران العشير واللعن وعدم الصبر وعدم الشكر ينتشر في النساء 《أكثر》 من الرجال\nوبقول تاني ربنا مش بيحاسب النساء عشان هم نساء ولا الرجال عشان هم رجال، ربنا بيحاسب على أفعال الرجال وأفعال النساء، \nأي واحد فيهم هيتعدى حدوده فالجزاء واحد\nعارفين كمان من الأسباب إللي ممكن تخلي النساء أكثر أهل النار إيه\nإن مثلا لو الرجل ظلم زوجته أو آذاها أو...أو...هو عمل حاجة واحدة، المرأة بقى تروح تحكي لصاحبتها، وتحكي لأختها وتحكي لأمها وتحكي لفلانة وعلانة، شوفوا بقى كام مرة اغتابت فيها زوجها، والغيبة كبيرة من الكبائر،\nفاحسبوا كم مرة وقعت في الكبيرة دي،\nوكم مرة الناس تعاطفوا معاها وراحوا شاتمينه وعملوا معاه الواجب، وكل ده عداد السيئات شغال للمرأة\nتخيلوا إن يوم القيامة ممكن الرجل يبجي قصاد ربنا عشان يحاسبه على ظلم زوجته فتكون النتيجة إنه بدل ما يتحاسب ويديها من حسناته؛ ميتحاسبش وممكن كمان ياخد من حسنات زوجته كمان\nلأن زوجته المظلومة ضيعت حقها بسبب الغيبة دي لوحدها، شوفوا بقى لو كمان حاولت تاخد حقها في الدنيا على أساس إنها مظلومة وكده ممكن تعمل إيه، \nفتيجي يوم القيامة وهي مفكرة نفسها مظلومة وفجأة تلاقي زوجها ده بياخد من حسناتها\n خدوا بالكم إن الميزان يوم القيامة بمثاقيل الذر \n\"وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا ۖ وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا ۗ وَكَفَىٰ بِنَا حَاسِبِينَ\"\nفكل واحد يمسك لسانه وميحكيش لحد إلا لو على سبيل حل مشكلة، بلاش الفضفضة الله يكرمكم، احنا مش حمل سيئات حد\nلو في أي نقطة مش واضحة في موضوع النهاردة أو حد عنده سؤال ياريت يسيب تعليق بسؤاله وأنا هجاوب عليه المرة الجاية إن شاء الله"}, {"n": 126, "l": "الجزء 100 | أحداث السنه السادسه من الهجره | إسلام ثُمامه ابن أُثال", "u": "https://www.facebook.com/groups/710210019782034/permalink/818841772252191/", "t": "اسلام ثُمامة بن أثال بعد م كان بيكره رسول الله \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_المائة\n#أحداث_السنة_السادسة_من_الهجرة\n#إسلام_ثُمامة_بن_أُثال\nبعد غزوة بني قريظة، رسول الله ﷺ وزّع سبي النساء على الصحابة، احنا كنا قلنا إن حكم الله فيهم هو قتل الرجال وسبي النساء والأطفال،\nكان وسط السّبْي امرأة اسمها ريْحانة بنت زيد، وكانت امرأة جميلة لها مكانة خاصة وسط قومها وكانت معروفة بكمال عقلها وحسن تدبيرها للأمور،\nوكانت متزوجة من رجل من قومها وكان يحبها ويكرمها، فلما قُتل مع بني قريظة وأصبحت من السّبْي كانت هي من نصيب رسول الله ﷺ،\nفعرض رسول الله ﷺ عليها الإسلام فلم تقبله وأصرت إنها تكون على اليهودية، فزعل رسول الله ﷺ إنها مش عايزة تدخل الإسلام،\nوفي يوم من الأيام في آواخر السنة الخامسة من الهجرة وبعد نزول آية الحجاب، كان رسول الله ﷺ قاعد مع مجموعة من أصحابه فسمع صوت نعلين، يعني صوت أقدام واحد بيقرب عليهم ،فقال لأصحابه :\nهذا ثعلبة بن سعية جاي يبشرني بإسلام ريحانة\nفدخل عليه ثعلبة وبشره فعلا بإسلام ريحانة، فذهب إليها رسول الله ﷺ وعرض عليها إنه يعتقها ويتزوجها ويضرب عليها الحجاب،\nلكنها قالت: بلاش تتزوجني يا رسول الله واجعلني في ملكك فكده أخف عليّ وعليك.\nفكانت هي أول ملك يمين لرسول الله ﷺ، وظلت في ملكه ﷺ حتى ماتت بعد حجة الوداع، واحنا كنا قلنا إن الأمة وملك اليمين الحجاب مش فرض عليهن زي الحُرة،\nوزوجات رسول الله ﷺ هن فقط أمهات المؤمنين، أما ملك يمينه ﷺ فليسوا بأمهات للمؤمنين \n☆سريعا كده، ملك اليمين أو السّبي يعني النساء إللي المسلمين أخذوهن أسرى في الحروب،\nوالرجل ممكن يكون عنده عدد غير محدود من ملك اليمين، ومش مُلزم إنه يعدل بين ما ملكت يمينه، هو ملزم فقط بالعدل بين زوجاته لو كان له أكثر من زوجة ويتحاسب لو قصّر في العدل بينهن،\nولو كانت المرأة متزوجة ووقعت في السبي، وأخذها رجل من المسلمين لا يحل له وطْأها يعني جماعها إلا إذا حاضت حيضة، ولو كانت حامل لا يطأها إلا لما تضع حملها،\nوالكلام ده عن السّبي من أهل الكتاب، أما السبي من الكفار عبدة الأوثان فلا يجوز للرجل وطأها حتى تُسلم\n◇السؤال بقى، ليه الإسلام ممنعش الرق أصلا\nشوفوا،\nكل طريق للرق والاستعباد استطاع الإسلام إنه يقفله، إلا طريق واحد وهو طريق الحرب،\nالإسلام لما جاء كان موضوع الرق ده موجود ومتعارف عليه في كل المجتمعات من زمن بعيد جدا، يعني هو أصلا كان حاجة طبيعية جدا في المجتمعات دي،\nفبدأ يصحح الأوضاع ويرفع الظلم إللي كان واقع على العبيد والأسرى بقوانين معينة،\nوكان المُتعارف عليه إن في الحروب لو حد وقع أسير إما يُقتل أو يُسترق يعني يبقى عبد أو أمة يُباع ويُشترى،\nوكانت الأمَة الواحدة متاع لسيدها وأبنائه وأصحابه وكل من يريد أن يستمتع بها،\nفجاء الإسلام ومنع الكلام ده، وأصبحت الأمة ملك لسيدها فقط\nفحصل بين المسلمين وأعداء الإسلام حروب، فكان من يقع أسير في أيدي الأعداء من المسلمين يُسترق وتُسلب حريته ويُعامل بالظلم،\nفكان الطبيعي المعاملة بالمثل، وهو إن إللي يقع أسير في أيدي المسلمين يسترق هو كمان، لكن الفرق إن الإسلام بيحفظ له حقوقه كعبد أو أمة\nفمش من الحكمة أبدا ولا من السياسة إن الإنسان يشجع عدوّه عليه\nيعني هو يأسر المسلمين ويسترقهم ويذيقهم ألوان الظلم ولو وقع في أيدي المسلمين أسرى يطلقوا سراحهم كده عادي ويزودوا أعداد أعدائهم ويجمعوا نفسهم تاني لقتل المسلمين وأعداد المسلمين تفضل تقل وهكذا\nأي منطق يقول بالكلام ده \nفمكنش ينفع إن الإسلام يأتي ويلغي السبي عن طريق الحرب، لأن كده هيبقى في ظلم، والإسلام دين العدل\nدي كانت بعض الأحداث المهمة من الناحية الاجتماعية، هنرجع دلوقتي للسرايا إللي رسول الله ﷺ كان بيرسلها لتأديب القبائل إللي شاركت في غزوة الخندق،\n☆لكن قبل ما نتكلم عن السرايا في واقعة يُقال إنها حصلت في السنة الخامسة للهجرة ومنتشرة بين الناس والخطباء على المنابر بيقولوها لكنها لم تثبت إنها حصلت وهي إن المدينة زُلزلت في عهده ﷺ فقال للناس : إن الله يستعتبكم فأعتبوه،\nكل الأحاديث إللي ورد فيها الحادثة دي غير صحيحة ولم تثبت الحادثة دي\nلكن حصل زلزلال في خلافة عمر بن الخطاب رضي الله عنه وقال للناس لو حصل زلزال تاني هخرج من بينكم ومش هقعد معاكم،\nلأن عمر بن الخطاب رضي الله عنه عارف إن الزلزال ماهو إلا عقوبة من الله على ما يفعله العباد من المنكرات وترك أوامره والمجاهرة بمعصيته، وربنا قال:\n\"قُلْ هُوَ الْقَادِرُ عَلَىٰ أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَحْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعًا وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ \nانظُرْ كَيْفَ نُصَرِّفُ الْآيَاتِ لَعَلَّهُمْ يَفْقَهُونَ\"\nفعمر رضي الله عنه خايف من عذاب ربنا فعشان كده قال إن لو حصل زلزال تاني هيخرج من المدينة،\n《ركزوا كده في قوله تعالى: وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ وشوفوا الواقع بتاعنا وإزاي ربنا فعلا بيسلط الناس على بعض \n》\nأرسل رسول الله ﷺ السرايا لتأديب القبائل، ودخلنا في السنة السادسة من الهجرة وهنا هتبدأ مرحلة جديدة للدولة الإسلامية وهي:\nمرحلة الانتشار والفتح والتمكين للدين، \nبعد ما المسلمين خلاص عدّوا أخطر مرحلة في حياة الدولة الإسلامية بعد الأحزاب وفشل الأحزاب بعد ما جمعوا كل الأعداد دي للقضاء على المسلمين جاء دور المسلمين زي ما رسول الله ﷺ قال:\nاليوم نغزوهم ولا يغزونا\nفبدأ رسول الله ﷺ يُرسل السرايا فكانت أول سرية بعد غزوة الخندق هي سَرِية عبد الله بن عتيك وإللي قتل فيها أبو رافع اليهودي وحكينا قصته،\nالسرية التانية إللي خرجت بعده كانت سرية محمد بن مَسلمة، أرسله رسول الله ﷺ مع مجموعة من أصحابه لتأديب بني بكر بن كلاب من قبائل نجد إللي اشتركوا في الأحزاب ، \nوكان مكانها يبعد عن المدينة بحوالي ثلاثمائة كيلو متر، عدد السرية دي كان ثلاثين صحابي يعني عدد بسيط جدا بالنسبة لقبيلة كاملة،\nومع ذلك هرب معظمهم خوفا من سرية محمد بن مسلمة وألقى الله في قلوبهم الرعب، \nواستطاع محمد بن مسلمة إنه يقتل عشرة منهم وتفرقوا في الصحراء واستطاع إنه يَغنم عدد كبير جدا من الإبل والأغنام، \nفكان من آثار السرية دي إن هيبة المسلمين ارتفعت وسط الأعراب والناس خافوا منهم، \nوكمان معنويات المسلمين ارتفعت والوضع إلاقتصادي للمسلمين اتحسن بعد ما كانوا في حالة فقر شديد جدا\nبعد ما السرية خلّصت مهمتها وخلاص راجعين للمدينة قابلوا رجل من أهل نجد فأسروه على أساس إنه كان من الجيش إللي هرب،\nأخذوا الرجل ورجعوا للمدينة، فلما رآه رسول الله ﷺ قال لهم : انتم عارفين مين الرجل إللي أسرتوه ده؟!!\nفالصحابة قالوا له : لأ\nفقال لهم رسول الله ﷺ: ده ثُمامة بن أُثَال سيد بني حنيفة\n☆ثمامة بن أُثال كان أمير منطقة اسمها اليمامة في البحرين وهو من أعظم سادات العرب في الوقت ده، يعني زي ما تقولوا رئيس دولة من الدول الكبيرة في عصرنا دلوقتي\nفالمسلمين أسروه من غير ما يعرفوا مكانته ولا هو كان مين،\nفقال لهم رسول الله ﷺ أحسنوا إليه، \nفكانوا يأتوه بالطعام ويحسنوا معاملته، وربطوه في عمود من عواميد المسجد عشان يشوف صلاة المسلمين ويسمع القرآن ويشوف أخلاق المسلمين يمكن يتأثر ويُسلم،\nوكان رسول الله ﷺ كل يوم يمر عليه ويسأله:\nماذا عندك يا ثُمامة؟ \nفقال له ثُمامة:\nعندي خير، إن تَقتُل تقتُل ذا دم، وإن تُنعم تُنعِم على شاكر، وإن أردت المال فسلْ تعطَ منه ما تشاء\nيعني رسول الله ﷺ بيسأله عن حاله وإيه الاختيارات إللي عنده عشان يفدي نفسه،\nفثمامة قال له لو قتلتني قومي مش هيسبوك وهييجوا يثأروا منك، ولو عفوت عني مش هنسى لك الجميل ده،\nولو كنت عايز مال مقابل انك تسيبني فاطلب إللي انت عايزه.\n☆ثمامة كان من أغنى أغنياء العرب، فده يُعتبر عرض مغري جدا لرسول الله ﷺ لأن المدينة في حالة اقتصادية صعبة جدا، \nلكن رسول الله ﷺ كان همه أكبر من كده بكثير،\nرسول الله ﷺ شاف إن ثمامة رجل عاقل وسيد وشريف وزعيم قومه، فلو أسلم هيسلم من وراه ناس كثيرة، فمكنش بيرد عليه، كان بيحسن إليه ويتكلم معاه،\nكان يسمع العروض بتاعته دي ويسيبه ويمشي، ويجيله تاني يوم ويسأل نفس السؤال، ماذا عندك يا ثُمامة، وثمامة يرد بنفس الإجابة عندي خير إن تقتل تقتل ذا دم.....\nبعد ما عدّى كم يوم وثمامة شاف تعامل الصحابة وأخلاقهم وسمع القرآن وشاف صلاة المسلمين جاء رسول الله ﷺ وسأله السؤال المعتاد وجاوبه ثمامة بنفس الجواب،\nولاحظ رسول الله ﷺ انبهار ثمامة بن أثال بالمسلمين وبطبيعة الدين الإسلامي، ولاحظ انبهاره به هو ﷺ،\nففكر رسول الله ﷺ إنه لو أطلق ثمامة بدون ما يدفع فدية ممكن ده يكون حافز له على الدخول في الإسلام،\nوكان إسلام نفس واحدة وإنقاذها من النار أحب إلى رسول الله ﷺ من كل أموال الدنيا، فاختار رسول الله ﷺ إنه يطلق سراح ثمامة وقال للصحابة : أطلقوا ثمامة\nفأطلقوه، وخرج ثمامة من المسجد وراح ناحية نخل قريب من المسجد وعنده بئر فاغتسل، \nوالظاهر إنه كان سأل حد من الصحابة عن كيفية الدخول في الإسلام لما كان مربوط،\n بعد ما اغتسل دخل المسجد وقال أمام رسول الله ﷺ وأمام الصحابة:\n\"أشهد ألا إله إلا الله وأن محمدا رسول الله \"\n☆ثمامة مرضاش يُسلم وهو في المسجد مأسور عشان محدش يتهمه بالنفاق وإنه أسلم عشان يطلع من المشكلة إللي هو فيها،\nانتظر لحد ما بقى حر ورجع تاني بكامل إرادته يعلن إسلامه.\n قال ثمامة لرسول الله ﷺ بعد قول الشهادة:\nوالله يا محمد ما كانت أكره على وجه الأرض رجل زي ما بكرهك، ودلوقتي بقى وجهك أحب الوجوه إليّ،\nووالله ما كان في دين أكرهه زي ما بكره دينك، فبقى دينك أحب إليّ من أي دين،\nومكنش في بلد بكرهها زي ما بكره بلدك فبقت بلدك أحب البلدان إليّ\nوأنا كنت في طريقي للعمرة فأسرني أصحابك، فأنا أعمل إيه دلوقتي\nفقال له رسول الله ﷺ:\nروح كمّل عمرتك\nفدخل مكة وهو يقول تلبية الإسلام، فكان هو أول مسلم يدخل مكة معتمرا ويلبي بتلبية الإسلام وقال:\nلبيك اللهم لبيك، لبيك لا شريك لك لبيك، إن الحمد والنعمة لك والملك لا شريك لك،\nفسمعه كفار مكة وكان مقرب منهم وعارفينه كويس فتجمعوا عليه وقالوا له:\nإنت صبأت\nيعني تركت دين العرب،فقال لهم ثمامة:\nلا، ولكني أسلمت مع محمد ﷺ، يعني إللي كنت عليه من عبادة الأصنام هو الباطل وأنا دلوقتي آمنت فعلا مش صبأت\nوأخذ قرار في منتهى الجرأة\nقال لسادات مكة: والله لا يأتيكم حبة قمح حتى يأذن بها رسول الله ﷺ \nقرر إنه يعمل عليهم حصار اقتصادي، والحصار ده سببه إن مكة بتعادي المسلمين، \nوالقرار ده جريء لأنه هيقف ويواجه مكة بكل قوتها وعلاقتها الخارجية، ده غير الخسائر المالية إللي هيعرض نفسه وقبيلته لها،\nاليمامة هي المصدر الرئيسي لشعير وخبز مكة، لدرجة إن كان بيُقال على اليمامة إنها ريف مكة، فتخيلوا بيشتروا بكميات أد إيه،\n فكده اليمامة هتخسر أموال كثيرة جدا، ومع ذلك مهموش، هو همه رفع راية الإسلام وعزته\nوصل الخبر لرسول الله ﷺ ولم يعترض على فعل ثمامة، فالمقاطعة نوع من أنواع الحرب،\nارتفعت الأسعار في مكة بسبب المقاطعة وبدأت تحصل فيهم مجاعة، حاولوا إقناع ثمامة بإنه يفك الحصار ويرسل لهم القمح، لكن ثمامة مصمم إنهم لن يأخذوا القمح إلا بعد موافقة رسول الله ﷺ،\nاجتمع سادة مكة عشان يشوفوا حل للموضوع، مفيش غير حل واحد وهو إنهم يرسلوا وفد لرسول الله ﷺ في المدينة يستعطفوه ويقنعوه إنه يقول لثمامة إنه يفك الحصار عن مكة ويرسل لهم القمح،\nشايفين المُعز المُذل\nلسه بس من كم شهر قريش كانت محاصرة المدينة وبتهدد المسلمين، دلوقتي هم إللي جايين في كل ذل وانكسار بيستعطفوا رسول الله ﷺ ويستحلفوه بالرحم إللي بينه وبينهم إنه يأذن لثمامة بإرسال القمح لهم مرة ثانية\nوعلى الرغم من إللي قريش عملوه مع رسول الله ﷺ السنين إللي فاتت دي إلا إنه ﷺ كان رقيق القلب، \nفوافق على عودة التجارة مرة أخرى بين مكة واليمامة وأنهى الحصار إللي كان مفروض على مكة،\nوطبعا الموقف ده كان في مصلحة الدولة الإسلامية ورفع رأس المسلمين وسط العرب، فبعد ما كان المسلمين مطاردين من أهل مكة وكانوا دولة ضعيفة،\nبقت دولة الإسلام دولة قوية تفرض سيطرتها هنا وهناك لدرجة إنها بقت تتحكم في طعام أهل مكة ولا يأتيهم القمح إلا بإذن زعيم الدولة الإسلامية رسول الله ﷺ \nوكل ده كان بسبب سرية محمد بن مسلمة إللي كانت مكونة من ثلاثين فارس فقط\nرسول الله ﷺ استمر في إرسال السريا لتأديب القبائل، \nوخرج هو بنفسه على رأس جيش لقتال قبيلتي عَضل والقارة إللي غدروا بالصحابة في حادثتي ماء الرجيع وبئر معونة إللي اتكلمنا عنهم قبل كده،\nالمرة الجاية إن شاء الله هنتكلم عن السرايا كلها إللي حصلت في النصف الأول من السنة السادسة للهجرة، ونشوف الغزوة إللي رسول الله ﷺ خرج فيها كانت إيه نتائجها"}, {"n": 127, "l": "الجزء 101 | السيره من بداية 101 | الجزء 101 | أحداث السنه السادسه من الهجرة | السرايا المتتاليه لتأديب الأحزاب | غزوة الغابة او ذي قَرد", "u": "https://www.facebook.com/groups/710210019782034/permalink/818843268918708/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد\n#أحداث_السنة_السادسة_من_الهجرة\n#السرايا_المتتالية_لتأديب_الأحزاب\n#غزوة_الغابة_أو_ذي_قَرَد\nقلنا المرة إللي فاتت إن رسول الله ﷺ أرسل سرايا متتالية لقتال القبائل والأشخاص إللي شاركوا في حصار المدينة،\nواتكلمنا عن غزوة عبد الله بن عتيك ومحمد بن مسلمة،\nبعد ما رجعت سرية محمد بن مسلمة أرسل رسول الله ﷺ سرية تانية وهي سرية عكاشة بن محصن الأسدي،\nأرسله مع أربعين رجل من الصحابة لمكان اسمه الغَمْر، فيه تجمّع قبيلة لبني أسد،\nلما عرف بنو أسد إن في سرية جاية تهجم عليهم أخفوا الأنعام بتاعتهم في مكان بعيد وهربوا كلهم،\nفلما وصل عكاشة رضي الله عنه ملقاش حد في القرية خالص\nلكنه شاف أثار الأنعام يعني بواقي أكلها وفضلاتها، فلقى رجل نائم فسأله عن أهل القرية قال له أنهم هربوا،\nوسألوه عن الأنعام فقال لهم ميعرفش، فعرفوا إنه بيخدعهم فهددوه، فأخبرهم عن مكان الأنعام وراحوا وأخذوا الأنعام ورجعوا بها للمدينة،\nأرسل رسول الله ﷺ محمد بن مسلمة في سرية تانية ومعاه عشرة من الصحابة لبني ثعلبة في مكان قريب من المدينة مكان اسمه ذي القَصّة،\nوصل محمد بن مسلمة للمكان بالليل وكان بني ثعلبة وصل لهم خبر السرية فعملوا كمين مكون من مائة رجل واختبأوا للصحابة العشرة وقعدوا يراقبوهم،\nفلما نام الصحابة تسلل المائة رجل من بني ثعلبة ودخلوا وسطهم فانتبه محمد بن مسلمة وصرخ في أصحابه: السلااااح \nفكلهم قاموا وقعدوا يقاتلوا المائة رجل، فرموهم بالرماح فقتلوا العشرة من الصحابة وسقط محمد بن مسلمة جريحا،\nضربوا قدمه لم يتحرك ففكروا إنه مات فخلعوا ملابسه ومشيوا وتركوه،\nواحد من المسلمين كان معدي على المكان قدرا كده فشاف القتلى من الصحابة فاسترجع وقال: إنا لله وإنا إليه راجعون\nفسمعه محمد بن مسلمة فنادى عليه وعرف إنه لسه عايش فأخذه ورجع به للمدينة،\nوصل الخبر لرسول الله ﷺ فجهز سرية تانية بسرعة بقيادة أبو عبيدة عامر بن الجراح ومعاه أربعين رجل يروحوا للمكان إللي قُتل فيه الصحابة عشان يقتلوا من قتلهم،\nوصلت سرية أبو عبيدة للمكان وملقوش حد هناك، لكن لقوا أغنام وبعير فأخذوها ورجعوا بها للمدينة،\n☆وأبو عبيدة كان من أوائل الصحابة إللي أسلموا على يد أبي بكر رضي الله عنه، وسماه رسول الله ﷺ أمين هذه الأمة، قال رسول الله ﷺ :\n\"لِكُلِّ أُمَّةٍ أَمِيْنٌ، وَأَمِيْنُ هَذِهِ الأُمَّةِ: أَبُو عُبَيْدَةَ بنُ الجَرَّاحِ\"\nيعني في كل أمة من الأمم بيكون فيها رجل يتميز بالثقة وشدة الأمانة، \nوأمين أمه الإسلام هو أبو عبيدة عامر بن الجراح، لكن مش معنى كده إن باقي الصحابة مفيهمش صفة الأمانة\nهم كلهم أمناء لكن الصفة دي زايدة جدا عند أبو عبيدة، زي ما رسول الله ﷺ وصف بعض الصحابة ببعض الأوصاف:\n\"أرحم أمتي بأمتي أبو بكر، وأشدهم في أمر الله عمر، وأصدقهم حياء عثمان، \nوأعلمهم بالحلال والحرام معاذ بن جبل، وأفرضهم زيد بن ثابت، وأقرؤهم أبيّ، \nولكل أمة أمين وأمين هذه الأمة أبو عبيدة بن الجراح\"\nكل الصحابة فيهم الصفات دي لكن كل واحد بيغلب عليه صفة أكثر من التانية بيتميز بها\nفي شهر ربيع الآخر أرسل رسول الله ﷺ سرية بقيادة زيد بن حارثة رضي الله عنه لقتال بني سُلَيم،\nوصل لمنطقة اسمها الجَمُوم ووجد هناك امرأة فسألها فأخبرتهم عن مكان فيه أغنام ومرعى لبني سليم،\nفذهب زيد وإللي كانوا معاه للمكان فأخذوا الأغنام وأسروا من كان في المكان ومن بينهم زوج المرأة،\nفلما رجعوا لرسول الله ﷺ ومعهم المرأة وزوجها أطلقها رسول الله ﷺ ووهب لها زوجها،\nفي شهر جمادى الأولى أرسل رسول الله ﷺ زيد بن حارثة في سرية تانية لمكان اسمه العِيص ومعاه مائة وسبعين رجل من الصحابة، وكان سبب السرية دي إن رسول الله ﷺ سمع إن في قافلة لقريش جاية من الشام فأراد إنه يعترضها،\nففعلا اعترضها وأخذ القافلة ورجع بها للمدينة،\nوكان في القافلة دي أبو العاص بن الربيع زوج زينب بنت رسول الله ﷺ وكان لسه على الكفر، واحنا حكينا قصته في الجزء الثالث والستين وإنه أسلم بعد ما رجع لمكة،\nفممكن تبقوا ترجعوا للقصة تاني لو حابين تفتكروها \nفي نفس الشهر خرج رسول الله ﷺ بنفسه لقتال قبائل عضل والقارة فاكرينهم؟\nإللي غدروا بالصحابة في حادثتي ماء الرجيع وبئر معونة،\nرسول الله ﷺ لم ينسَ غدر القبيلتين وأول ما وجد الفرصة للانتقام لمقتل أصحابه جهز جيش للخروج لقتالهم،\nوعضل والقارة من قبيلة كبيرة جدا اسمها بنو لَحْيان، \nلكن الموضوع مش سهل \nلأن قبائل بني لحيان قبائل قوية مقاتلة، ومشهورة بالغدر وقطع الطرق ومكانها بعيد عن المدينة بحوالي أربعمائة كيلو متر،\nفتخيلوا كمية الكمائن إللي هتكون على الطريق، ده غير إن القبائل دي قريبة جدا من مكة، فمش بعيد أهل مكة يسمعوا الخبر فيجهزوا جيش ويخرجوا يقاتلوا مع بني لحيان،\nفكانت الغزوة دي تعتبر خطيرة على رسول الله ﷺ وعلى جيش المسلمين،\nلكن رسول الله ﷺ كان عنده خطة، جهز مائتين فارس وأوهم الناس إنه متجه ناحية الشمال في بادية الشام، وبعدين راح مغير الاتجاه وتحرك ناحية الجنوب في اتجاه ديار بني لحيان عشان ميوصلهمش الخبر،\nلكن بني لحيان حاطين كمائن كثيرة جدا فعرفوا بقدوم رسول الله ﷺ فرجعوا لقومهم وأخبروهم بمجيء رسول الله ﷺ فهربوا كلهم منه ﷺ \nمع إن العدد إللي كان مع رسول الله ﷺ كان عدد قليل لكنهم اترعبوا من رسول الله ﷺ وهربوا وتركوا بيوتهم فاضية،\nرسول الله ﷺ مكنش عايزهم يهربوا هو كان عايز يقاتلهم عشان ينتقم لأصحابه الذين قُتلوا غدرا،\nلكن هروب بني لحيان كان له أثر كبير جدا لصالح المسلمين في المنطقة، لأن العرب مكنش من أخلاقهم الهروب، \nوالجُبْن صفة مذمومة جدا عندهم وخصوصا لو قبيلة قوية زي بني لحيان،\nفلما العرب تسمع إن بني لحيان القبيلة القوية إللي لها تاريخ في القتال هربت من المسلمين من غير حتى ما يواجهوهم كده الناس هتفكر ألف مرة قبل ما يقاتلوا المسلمين،\nومش بس كده ده رسول الله ﷺ قعد في ديارهم يومين وبقى هو إللي يدور عليهم عشان يقاتلهم مش لاقيهم،\nفكده أثبت للجميع إنه مش خايف من بني لحيان وهم إللي خايفين منه\nفكل ده كان في صالح المسلمين والدولة الإسلامية، رسول الله ﷺ بقاله أسبوعين غائب عن المدينة، فبعد ما رجع رسول الله ﷺ من الغزوة ، واحد اسمه عُيينة بن حصن سيد قبائل غطفان وكان من المشاركين في الأحزاب أغار على أطراف المدينة،\nعيَيْنة بن حصن ده كان لقبه وسط الناس الأحمق المُطاع \nجمع مجموعة من الفرسان من قومه وهجم على أطراف المدينة على منطقة اسمها الغابة بترعى فيها إبل المسلمين،\nكان في المكان ده زوجة أبي ذر الغفاري وابنه وراعي للإبل، فقتلوا ابن أبي ذر واخذوا زوجته أسيرة وأخذوا الإبل،\nوالكلام ده كان قبل أذان الفجر على طول، شاف الموقف غلام لعبد الرحمن بن عوف،\nجري على طول للمدينة عشان يخبر رسول الله ﷺ باللي حصل، قابله واحد من الصحابة اسمه سَلَمة بن الأَكْوَع وأخبره باللي حصل، راح طالع سلمة بن الأكوع على جبل باتجاه المدينة ونادى بأعلى صوته : \nيا صباحاه....يا صباحاه....يا صباحاه! \nأهل المدينة كلهم سمعوه فعرفوا إن في مشكلة، وسمع رسول الله ﷺ صرخة سلمة وجاء لرسول الله ﷺ ثمانية من فرسان الصحابة منهم المقداد بن عمرو وأبو قتادة وغيرهم من الصحابة عشان يكونوا تحت أمر رسول الله ﷺ، \nفأمّر عليهم سعد بن زيد، يعني خلاه هو أمير الثمانية وقال لهم يلحقوا بسَلمة على ما رسول الله ﷺ يجمع الناس ويلحق بهم،\nفي الوقت ده كان سلمة بن الأكوع أخذ سيفه والنبل بتاعه وطلع يجري وراء العدو، لوحده بطوله كده، وهم كانوا بالمئات وكان سلمة أسرع العرب محدش يقدر يلحقه كان حتى أسرع من الخيل\nورسول الله ﷺ كان يقول عنه خير رجالاتنا سلمة بن الأكوع، يعني أحسن واحد بيعرف يجري ويقاتل على رجله سلمة بن الأكوع رضي الله عنه،\nلحقهم سلمة وكان بيضع علامات في الطريق عشان يرشد رسول الله ﷺ لمكانه، وقعد يرميهم بالسهام، \nوهم يجروا قصاده خايفين منه، ولما كانوا يحاولوا يرجعوا له يقوم هو يهرب في الاتجاه التاني ومحدش يقدر يلحقه،\nفلما يسيبوه ويمشوا يقوم راجع لهم تاني، وكان لما ييجي مكان ضيق يعدوا منه كان يطلع على الجبل ويرميهم بالحجارة من فوق الجبل،\nواترعبوا من سلمة لدرجة إنهم بقوا يرموا الأحمال إللي معاهم ويتخففوا منها، \nرموا الرماح وتركوا الإبل إللي كانوا سرقوها وهربت منهم زوجة أبي ذر ورجعت للمدينة،\n تعبوا من كتر الجري والقتال فقعدوا يستريحوا شوية وكان الكلام ده وقت الضحى ومفكرين إن سلمة خلاص رجع، لقوه من فوق الجبل بيرمي عليهم حجارة تاني\nفاترعبوا منه وقال لهم عيينة لولا إن الرجل ده وراءه جيش مكنش هيقاتل بالشجاعة دي، وقال لأربعة منهم معاه يقوموا يحاوطوه ويأسروه،\nفقاموا إلى سلمة فقال لهم :\n\"أتعرفونني أنا ابن الأكوع والذي كرّم وجه محمد لا يطلبني رجل منكم فيُدركني ولا أطلبه فيفوتني\"\nيعني بيقول لهم عارفين انا مين ؟ أنا ابن الأكوع والله محدش هيجري ورايا منكم ويقدر يمسكني، ومفيش واحد فيكم هجري وراه إلا وهمسكه \nفخافوا منه ورجعوا،\nنظر سلمة لقى غبار فرسان رسول الله ﷺ جاية من ناحية المدينة، فكان أول واحد يصل لسلمة هو واحد اسمه الأَخْرم الأسدي ومن ورائه أبو قتادة فمسك سلمة بزمام فرس الأخرم والزمام يعني الحبل إللي بيمسك الفرس عشان ميجريش وقال للأخرم:\n\"يا أخرم احذر القوم فإني أخاف أن يَقْطَطِعوك فائّتِد\"\nيعني بيقول له استنى وخد بالك أنا خايف عليك أحسن يقتلوك، فقال له الأخرم:\nيا سلمة لو كنت تؤمن بالله واليوم الآخر وتعلم أن الجنة حق والنار حق، فمتقفش بيني وبين الشهادة\nفترك سلمة فرس الأخرم فقابله حبيب بن عيينة بن حصن فقتله وتحققت رؤياه ومات شهيدا\n☆الأخرم كان شاف رؤيا قبل الموقف ده بكم يوم إن السماء اتفتحت حتى السماء السابعة وقيل له : هذه منزلتك!\nفراح الأخرم لأبي بكر وأخبره بالرؤيا وكان أكثر واحد بيعرف يفسر الرؤَى، فقال له أبكر الصديق:\nيا أخرم الرؤيا معناها إنك هتموت شهيد\nعشان كده لما سلمة وقّفه قال له الكلام إللي قاله، \nشاف الموقف أبو قتادة فانطلق وراء حبيب بن عيينة فقتله وجاء باقي الفرسان وانطلقوا خلف المشركين،\nفقتل عكاشة رجل وابنه برمح واحد وهم راكبين على نفس البعير،\nأما أبو قتادة فانطلق في مقدمة الناس فقابل رجل اسمه مِسعدة الفزاري،\nومسعدة ده له قصة مع أبو قتادة، لما كان أبو قتادة رضي الله عنه بيشتري الفرس إللي هو راكبه ده من السوق قابله مسعدة الفَزَاري فقال له مسعدة وهو مشرك :\nإيه الفرس ده\nفقال له أبو قتادة : \nدي فرس هقاتل عليها مع رسول الله ﷺ\nفقال مسعدة : \nما أهوَن قَتلكم وأشد جرأتكم\nيعني انتم ضعفاء أصلا وهنقدر نقتلكم بسهولة على الرغم من جرأتكم،\nفقال له أبو قتادة : \nأسأل الله أن أقابلك عليها وأقتلك\nفقال له مسعدة باستهزاء: آمين\nفاستجاب الله دعاء أبي قتادة والتقى بمسعدة الفزاري على الفرس إللي اشتراها وقاتل مسعدة وهو عليه وقتله أبو قتادة رضي الله عنه،\n وكان إللي يقتل واحد من المشركين يأخذ سَلْبه يعني ياخد الأغراض بتاعته،\nفوضع أبو قتادة بُردته، رداءه يعني على مسعدة عشان الناس تعرف إن أبو قتادة هو إللي قتله فمحدش يأخذ سلْبه،\nوانطلق وراء المشركين يطاردهم، في الوقت ده كان وصل رسول الله ﷺ ومعاه جيش من المسلمين،\nفلما رأى الناس بُردة أبي قتادة استرجعوا وحزنوا، فكروا إن إللي مقتول ده هو أبو قتادة،\nفقال لهم رسول الله ﷺ:\nليس بأبي قتادة، ولكنه قتيل لأبي قتادة وضع عليه بردته عشان تعرفوا إنه قتيله\nاجتمع الناس مع رسول الله ﷺ ونزلوا في مكان اسمه ذي قَرَد وقعدوا هناك يوم وليلة وهرب عيينة بن حصن وإللي كانوا معاه، واتسمت الغزوة دي باسم غزوة ذي قَرَد أو غزوة الغابة،\nجاء سلمة بن الأكوع لرسول الله ﷺ يقول له:\nخليني آخذ مائة رجل وأنا أروح وراهم وأقتلهم \nفقال له رسول الله ﷺ:\nهتعمل كده فعلا؟! فقال له سلمة : نعم والذي بعثك بالحق\nفضحك رسول الله ﷺ حتى ظهرت أسنانه ﷺ من جرأة وشجاعة سلمة بن الأكوع رضي الله عنه وقال له:\nده همّ خلاص وصلوا لديارهم وقاعدين بياكلوا\nوقال رسول الله ﷺ عن سلمة بن الأكوع:\nخير رجالاتنا سلمة بن الأكوع وخير فرساننا أبو قتادة.\nوطبعا رسول الله ﷺ بياخد بالأسباب ومش بيدخل معركة إلا وهو مجهز نفسه، يعني هو فقط يقدر يخلص المرأة وينقذ الإبل وكل ده في حدود المدينة،\nلكن ميقدرش ياخد الجيش ويتوجه لقبائل غطفان القوية من غير ما يكون واخد احتياطاته ومجهز الجيش كويس،\nأيوة هو لسه منتصر على بني لحيان القوية لكن غطفان أقوى منهم بكثير فمش هينفع يدخل بالمسلمين مغامرة غير مأمونة\nرجع رسول الله ﷺ مع الصحابة إلى المدينة وركّب سلمة خلفه على ناقته ﷺ،\nوهم في الطريق واحد كان عايز يسلي نفسه فقال :\nألَا من مُسابق للمدينة\nيعني مفيش حد يتسابق معايا للمدينة، وقعد يكرر الكلام، وسلمة بن الأكوع ساكت\nفلما زودها أوي وفضل يلح قال له سلمة: \nًألا تُكرم كريما ولا تهابُ شريفا\nيعني هو مفيش حد مالي عينك وانت الوحيد في الدنيا إللي بتعرف تجري يعني،\nفقال الرجل : نعم، إلا رسول الله ﷺ \nيعني مفيش حد في دماغي، ولا فارق معايا حد غير رسول الله ﷺ، فالكلام استفز سلمة رضي الله عنه\nفقال سلمة لرسول الله ﷺ:\nتأذن لي أسابقه يا رسول الله \nفقال له رسول الله ﷺ: لو انت عايز تسابقه روح سابقه!\nفنزل من خلف رسول الله ﷺ وقال للرجل : \nخلينا نبدأ السباق\nوبدأوا السباق من هنا ومفيش دقائق وكان سلمة بن الأكوع  سابقه بمرحلتين\nيعني الرجل التاني كان جاي بيجري وجايب أخره وسلمة رضي الله عنه واقف واخذ نفسه وأول ما الرجل وصل عند سلمة راح سلمة جاري وسابقه بمرحلتين تاني، وطبعا أكيد عرفنا مين إللي فاز بالسباق \n☆ملحوظة : في علماء قالوا إن غزوة ذي قَرَد كانت في أواخر السنة السادسة من الهجرة، لكن الراجح إنها كانت في أوائل السنة السادسة من الهجرة.\nفي شهر جمادى الآخرة أرسل رسول الله ﷺ سرية بقيادة زيد بن حارثة مرة ثالثة إلى بني ثعلبة ومعاه خمسة عشر رجلا لمكان اسمه الطّرف،\nفلما وصل ملقاش حد، كلهم هربوا فكروا إن رسول الله ﷺ هو إللي جاي يقاتلهم،\nفغنم زيد عشرين بعيرا وشاة، وتوجه للمدينة، فلما وصل لهم الخبر إن زيد هو إللي جاء خرجوا وراه وحاولوا يسترجعوا البعير إللي أخذه لكنهم معرفوش،\nفي نفس الشهر جمادى الآخرة بعد ما رجع زيد للمدينة أرسله رسول الله ﷺ مرة رابعة في سرية لمنطقة اسمها الحَسْمى في شمال الجزيرة العربية،\nوالسرية دي قصتها طويلة فهنخليها للمرة الجاية إن شاء الله، لكن هنلاحظ هنا إن رسول الله ﷺ بيُخرج زيد أكثر واحد في السرايا وبيجعله قائد لها ولسه كمان في سرايا تانية هيكون هو القائد فيها، فكأن رسول الله ﷺ بيدرب زيد رضي الله عنه لحاجة مهمة في المستقبل\nإيه إللي حصل في سرية الحسمى وكان إيه سببها أصلا، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 128, "l": "الجزء 102 | احداث السنه السادسه من الهجرة | غزوة بني المصطلق", "u": "https://www.facebook.com/groups/710210019782034/permalink/819345595535142/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنين\n#أحداث_السنة_السادسة_من_الهجرة\n#غزوة_بني_المصطلق\nكنا واقفين المرة إللي فاتت عند خروج زيد بن حارثة في سرية رابعة لمكان اسمه الحَسْمى،\nليه رسول الله ﷺ أرسله للمكان ده ومعاه خمسمائة مقاتل؟ يعني دي أول سرية تخرج بعدد كبير جدا كده\nهنرجع بالزمن للوراء شوية، صحابي اسمه دِحْيَة الكلبي، كان في زيارة لهِرَقل ملك الروم في الشام وكان هرقل أعطاه هدايا وملابس، وهو راجع للمدينة اعترض طريقه واحد من زعماء قبيلة جُذام،\nوالقبيلة دي تسكن في شمال الجزيرة العربية، والزعيم ده كان اسمه الهُنَيْد بن عُوص وكان معاه ابنه ومجموعة من الرجال، هجموا على دِحية رضي الله عنه وأخذوا الهدايا إللي كانت معاه وحتى أخذوا ملابسه وتركوا له ثوب قديم مقطع،\nسمع بالموضوع ده مجموعة من قبيلة بني الضّبِيب وكانوا مسلمين فاجتمعوا وراحوا ينقذوا دحية،\nوفعلا استطاعوا إنهم يرجعوا لدحية كل الحاجات إللي أخذها الهنيد بن عوص وإللي كانوا معاه،\nأخذ دحية الكلبي حاجاته ورجع للمدينة وأخبر رسول الله ﷺ إللي حصل معاه،\nالمعروف عند ناس كثير إن خلاص كده الموقف انتهى، حاجته اتسرقت ورجعناها وانتهى الموضوع ومفيش داعي للمشاكل\nلكن رسول الله ﷺ كان له رأي تاني وموقف تاني\nقرر رسول الله ﷺ إن الموقف ده ميعديش من غير ما ياخد موقف،\nأيوة إللي أخذوه من دحية رجع تاني لكن لازم وقفة عشان مش أي واحد تُسوّل له نفسه إنه يعتدي على المسلمين يفكر إنه هيعدي منها،\nإللي يعتدي على واحد مسلم أو امرأة كأنه اعتدى على الدولة الإسلامية كلها، فالموضوع لازم له وقفة عشان يعرفوا إن دماء وأعراض وحرمة المسلمين غالية\nوعلى فكرة الدولة إللي تحترم رعاياها وتدافع عنهم كده محدش يقدر يعتدي على رعاياها بعدين والناس تعمل لهم ألف حساب،\nوهو ده إللي رسول الله ﷺ كان بيعمله بالضبط\nأي حد يعتدي على المسلمين مش هيعدي منها بدون ما يتعاقب، \nوالمسلمين نفسهم لما يحسوا إنهم مهمين والقائد بتاعهم بيهتم بيهم وبيدافع عنهم هيحسوا بالأمان والانتماء لدولة الإسلام وإنهم مش مجرد أعداد ملهاش قيمة\nفلأن رسول الله ﷺ فاهم المعنى ده كويس جهز سرية زيد بن حارثة وإللي كانت مكونة من خمسمائة صحابي عشان يروح يقاتل قبيلة جذام وخصوصا الهنيد وابنه ويعاقبهم على اعتدائهم على دحية رضي الله عنه\nمع إن المسافة بعيدة جدا، يعني قبيلة جذام بعيدة عن المدينة بحوالي ثمانمائة كيلو،\nيعني هيمشوا المسافة دي كلها في الصحراء وبعدين يقاتلوا قبيلة قوية عشان بس اعتدوا على رجل مسلم واحد\nخرج زيد رضي الله عنه بأكبر سرية جهزها رسول الله ﷺ حتى الآن واتجه لقبيلة جذام،\nوكان بيمشي بالسرية في الليل ويرتاح في النهار عشان محدش يعرف بخروج السرية وتبقى مفاجأة للقبيلة،\nوفعلا وصل زيد للقبيلة وهجم عليهم فجأة وقتل منهم عدد كبير وكان من بين القتلى الهنيد وابنه، \nوغنمت السرية ألف وخمسمائة بعير وشاة، وأخذ مائة سبي من النساء والأطفال،\nوكان انتصار السرية دي له أثر كبير جدا في كل الجزيرة العربية،\nالكل دلوقتي عرف إن أي حد هينتقص من هيبة الدولة الإسلامية بالاعتداء على أي فرد منها هيكون عاقبته زي عاقبة قبيلة جذام\nالغنائم إللي السرية دي أخذتها هتفرِق جدا مع المسلمين في المدينة لأن حالتهم الاقتصادية صعبة،\nرجعت السرية للمدينة ومعاها الغنائم، وبعدها على طول جاء لرسول الله ﷺ زيد بن رفاعة الجذامي وكان معاه كتاب بالأمان من رسول لأنه كان أسلم هو ومجموعة من قبيلة جذام، \nمع إن قبيلة جذام هم إللي نقضوا العهد مع رسول الله ﷺ باعتدائهم على دحية، لكن رسول الله ﷺ آثر إنه يكسب قلوب القبيلة بإنه يرجع الأموال والنساء والأطفال للقبيلة\nإللي يشوف الموقف يقول إن رسول الله ﷺ خسر غنائم كثيرة كانت هتفرق في اقتصاد الدولة الإسلامية،\nلكن رسول الله ﷺ لا يقاتل من أجل المال ولا الغنائم، لكنه يقاتل لنشر دين الله بين الناس ولإدخال الناس في الإسلام،\nموقف رسول الله ﷺ ثبّت المسلمين من قبيلة جذام وفي نفس الوقت كان سبب في إسلام من لم يُسلم من القبيلة،\nهو إيه إللي يجبر رسول الله ﷺ على التنازل عن الأموال والغنائم دي في ظل مجتمع عايش بس على الغارات إللي بيعملوها على بعض ويقتلوا وينهبوا الأموال\nفواضح جدا في نظرهم إن رسول الله ﷺ مختلف وإن المال مش مهم بالنسبة له وإن هدفه مختلف عن باقي الناس،\nوكمان السرية حققت الهدف الرئيسي من خروجها وهو إظهار هيبة الدولة الإسلامية وإظهار قوتها وإن محدش يقدر يعتدي على رعاياها في أي مكان، \nوإنها مبقتش الدولة الضعيفة إللي كانت محاصرة من كم شهر، وحتى أفرادها مبقوش المجموعة المطاردة إللي قريش كانت بتعذبهم قبل الهجرة، دي رسالة واضحة جدا لكل العرب زي ما رسول الله ﷺ قال:\nاليوم نغزوهم ولا يغزونا\nسمع رسول الله ﷺ إن قبيلة بني المُصْطِلِق بتجمع الناس وبتجهز جيش لغزو المدينة،\nفقبل ما يكملوا تجهيزاتهم كان رسول الله ﷺ مجهز جيش من سبعمائة مقاتل وأخذ الجيش وراح يقاتل بني المصطلق، \nوكان خرج مع جيش المسلمين مجموعة من المنافقين،\nوكان من عادة رسول الله ﷺ إنه لما يخرج للسفر أو للغزو يعمل قرعة بين زوجاته وإللي يطلع اسمها تخرج معاه ﷺ،\nفي الغزوة دي خرج سهم عائشة رضي الله عنها فأخذها معاه ،\nوطبعا رسول الله ﷺ مكنش بياخد معاه النساء إلا وهو عارف إنهم مش هيتعرضوا للخطر ولا هيقعوا أسرى في يد الأعداء\nلم يحصل قتال بين جيش المسلمين وبني المصطلق جيش المسلمين هجم عليهم فجأة عند منطقة اسمها المُرَيْسِيعْ، وانتصر جيش المسلمين على مقاتلي بني المصطلق وقتلهم، وأخذ المسلمون النساء سبي، واتعرفت الغزوة دي باسم غزوة بني المصطلق أو غزوة المُرَيْسِيع،\nقسّم رسول الله ﷺ الغنائم بين المسلمين، فكانت بنت ملكهم بَرّة بنت الحارث من نصيب الصحابي ثابت بن قيس فكاتبته، يعني اتفقت معاه إنه يطلق سراحها مقابل مال معين تدفعه له،\nراحت لرسول الله ﷺ وقالت له: \nقد أصابني من البلاء ما لم يخفَ عليك، فوقعت في السهم لثابت بن قيس بن شماس، فكاتبته على نفسي، فجئت أستعينك على كتابي\nيعني بتقول لرسول الله ﷺ انت شوفت إللي جرالي وانا من نصيب ثابت قيس واتفقت معاه إنه يطلق سراحي مقابل مال فجئت لك تساعدني،\nلأنها بنت سيد القبيلة فمتعودتش إنها تكون أمة مملوكة، طول عمرها عايشة في نعيم والناس بتخدمها، وكانت متزوجة من ابن عمها وقُتل مع إللي قتلوا في الغزوة دي،\nفقال لها رسول الله ﷺ:\nأقول لك على حاجة أحسن؟!\nفقالت له : إيه إللي احسن يا رسول الله\nفقال لها : أقضي عنكِ كتابك وأتزوجك\nفقالت: نعم يا رسول الله، موافقة\nوكان عمرها في الوقت ده حوالي خمسة عشرة سنة، يعني أكبر من السيدة عائشة بسنة أو أكثر قليلا،\nوصل الخبر للناس إن رسول الله ﷺ تزوج بَرّة بنت الحارث، فقالوا : إزاي أصهار رسول الله ﷺ يكونوا في السّبْي\nفكل الناس أطلقوا السبايا إللي كانوا معاهم من بني المصطلق إكراما لرسول الله ﷺ، \nوالنتيجة إن كل القبيلة أسلمت ببركة زواج برة بنت الحارث إللي سماها رسول الله ﷺ باسم جُوَيْرِيّة، \nفأصبحت جويرية بنت الحارث هي الزوجة السادسة لرسول الله ﷺ ،\nوقالت عنها السيدة عائشة: \" فما أعلم امرأة أعظم بركةً على قومها منها\"\nخلصت المعركة وتوجه الجيش للرجوع للمدينة، في الطريق حصلت أحداث كثيرة ومهمة\nأولها إن السيدة عائشة كانت لابسة عقد زي السلسلة كده فانقطع ووقع منها وضاع، والعقد ده كان بتاع أختها أسماء،\nرسول الله ﷺ قعد يدور عليه والناس قعدوا يدوروا عليه معاه،\nالمشكلة بقى إنهم مكنوش على وضوء وكمان مفيش ماء يتوضأوا به، والوقت هيعدي وعايزين يصلوا\nرسول الله ﷺ قعد يريح شوية ووضع رأسه في حِجر السيدة عائشة ونام،\nوالناس راحوا اشتكوا لأبي بكر الصديق رضي الله عنه، إن عائشة السبب في الأزمة إللي هم فيها دي،\nفراح لها أبو بكر وقعد يعاتبها ويقول لها :\nحبستِ رسول الله ﷺ وحبستِ الناس وعطلتي عليهم ومش معاهم ماء، وقال لها كلام كثير وهو بيعاتبها وكان بيطعن بيده في خاصرتها، يعني كأنه بيزقها كده، \nوهي قاعدة زي ماهي مش بتتحرك عشان رسول الله ﷺ نايم على رجلها فمش عايزاه يصحى،\nوكده رسول الله ﷺ هو كمان محتاج ماء عشان يصلي ومفيش ماء، فأنزل الله تعالى رخصة التيمم في الآية:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ ۚ وَإِن كُنتُمْ جُنُبًا فَاطَّهَّرُوا ۚ \nوَإِن كُنتُم مَّرْضَىٰ أَوْ عَلَىٰ سَفَرٍ أَوْ جَاءَ أَحَدٌ مِّنكُم مِّنَ الْغَائِطِ أَوْ لَامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ ۚ \nمَا يُرِيدُ اللَّهُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ\" \nفبسبب السيدة عائشة نزلت آية التيمم، وقال أسيد بن حُضير رضي الله عنه:\nماهي بأول بركاتكم يا آل أبي بكر\nفتيمموا وصلوا، وأرسل رسول الله ﷺ أُسيد بن حضير ومعاه مجموعة يدوروا على العقد، فأقام البعير إللي السيدة عائشة بتركب عليه لقى العقد  تحت البعير وأخذه وأعطاه لرسول الله ﷺ وانطلقوا يكملوا في الطريق لحد ما وصلوا لمكان فيه ماء، وهنا حصلت قصة تانية،\n☆قبل ما نعرف إيه إللي حصل عايزين نعرف الأول إيه  موضوع التيمم ده\nالتيمم هو نوع من الطهارة وهو بديل عن الوضوء أو عن الغُسل إذا لم يوجد الماء أو في ماء لكن مش هينفع يستخدمه بسبب مرض أو جَرح،\nأو المية الموجودة تكفي فقط للشرب، أو إذا كانت المياه المتوفرة  نجسة، في الحالات دي يجوز التيمم\n◇طريقة التيمم بقى إن الإنسان يقول :\n بسم الله وهو بينوي في قلبه إنه هيتيمم، وبعدين يضرب بكفّيه الأرض \n أو أي مكان فيه تراب طاهر ضربة واحدة وبعدين يمسح ظاهر كفه الأيمن بِرَاحة يده اليسرى، ويمسح ظاهر كفه الأيسر براحة يده اليمنى،\nيعني اليد اليسرى هتمسح ظهر اليد اليمنى، واليد اليمنى هتمسح ظهر اليد اليسرى، وبعدين يمسح وجهه بإيديه الإثنين، ويقول الأذكار إللي بتتقال بعد الوضوء عادي\nويجوز للإنسان إنه يصلي أكثر من صلاة بالتيمم الواحد، \nيعني لو صلى الظهر بتيمم وجاء وقت العصر يصلي بنفس التيمم،\nطبعا الكلام ده إذا لم يجد الماء أو لم ينتقض التيمم، لكن إذا وجد الماء خلاص يتوضأ وإذا انتقض التيمم ومفيش ماء يتيمم مرة ثانية، وإللي بينقض التيمم هو نفسه إللي بينقض الوضوء إللي هو :\n☆الخارج من السبيلين من البول أو البراز أو الريح ، أكل لحم الإبل،\n ☆زوال العقل سواء بجنون أو سُكر إن الواحد يبقى سكران يعني، أو النوم أو الإغماء.\n☆مس الفرج بشهوة على الراجح من أقوال العلماء.\n◇سؤال بقى، لو الإنسان ملقاش مية واجتهد إنه يدور على المية وملقاش فتيمم وصلى، وبعدين لقى المية يعمل إيه، يعيد الصلاة ولّا لأ\nلأ ميعيدش الصلاة خلاص، لأن رسول الله ﷺ جاءه رجلان وقد أدركتهما الصلاة فتيمما وصليا، ثم لما سارا وجدا ماءً بعد ذلك،\nفأعاد أحدهما الصلاة والوضوء ولم يعد الآخر، فقال النبي ﷺ للذي لم يُعد: \nأصبت السنة، وقال للآخر: لك الأجر مرتين\"\nيعني إللي لم يُعدِ الصلاة صح ودي السنة، أما التاني إللي صلى فله أجرين لإنه اجتهد واحتاط، لكن الصح إنه لا يعيد الصلاة مرة ثانية إذا وجد الماء،\nالكلام ده إذا فعلا مكنش لاقي الماء، واجتهد إنه يبحث عنه لحد ما بقى مفيش أي مجال إنه يلاقيه\nنرجع لجيش رسول الله ﷺ وهو في طريق العودة للمدينة، \nبعد ما لقوا المية بدأوا يسقوا الإبل بتاعتهم،\nوانتم عارفين الزحمة إللي بتكون عند الماء لما بيسقوا الإبل، وده يزق ده وده يزق ده، فحصل تدافع بين رجل من المهاجرين وكان أجير لعمر بن الخطاب رضي الله عنه وبين رجل من الأنصار وكان أجير لعبد الله بن أبي بن سلول،\nوهو كان حاضر في الغزوة دي مع بعض المنافقين،\nالمهم لما حصل بينهم تدافع الصحابي من المهاجرين كان لَعّاب، بيهرج كتير يعني ،فكسَع الأنصاري،\nالكسع معناه إن واحد يضرب التاني على مؤخرته بيده أو بمقدمة رجله، يعني زي ما بنقول ضربه بالشلوت\nالأنصاري غضب جدا من فعل المهاجري، وصرخ:\nيا معشر الأنصار \nوصرخ المهاجري: يا معشر المهاجرين\nوجاء الأنصار والمهاجرين وهتحصل مشكلة، جاء رسول الله ﷺ وقال لهم : ما بال دعوى الجاهلية؟\nيعني هتتخانقوا بسبب العصبية وهيحصل بينكم فتنة، فقالوا: لا يا رسول الله، ولكن اتنين اتخانقوا فكسع أحدهما الآخر\nفقال لهم رسول الله ﷺ : دعوها فإنها مُنتنة\n☆في علماء قالوا إن المقصود بمنتنة هنا إللي هي الكَسْعة، فرسول الله ﷺ بينهى عن الضرب بالطريقة دي، وفي قول تاني بيقول إن المقصود بمنتنة هنا هي العصبية.\nالمهم الكلام ده وصل لمين\nوصل لعبد الله بن أبي بن سلول، وطبعا هو أصلا متغاظ من المسلمين هو والمنافقين إللي معاه وكمان الانتصارات إللي وراء بعضها في الفترة الأخيرة زادت من غيظهم\nفقال بغضب للناس إللي كانوا قاعدين معاه وكانوا من المنافقين :\nأَوَقد فعلوها\nقد نافرونا و كاثرونا في بلادنا والله ما أعُدّنا و جلاليب قريش إلا كما قيل : سمّن كلبكَ يأْكُلك\nأما والله لئن رجعنا إلى المدينة ليخرجن الأَعزُّ منها الأذل\nيعني بيقول هي دي آخرتها، هم جاؤا بلادنا وزاحمونا وكانوا ضعفاء مطرودين وأول ما بقوا أقوياء نكروا الجميل وغدروا  وتهجموا علينا، \nوراح مزعق في الناس إللي معاه وقال لهم :\nانتم إللي جبتوه لنفسكم، رضيتم إنهم يقعدوا في بلدنا وقسمتم أموالكم معاهم ووالله لو منعتم أموالكم عنهم لتركوا بلدكم واتجهوا لبلد تانية\nوالله لما نرجع للمدينة لنخرجن الأعز منها الأذل \nيعني بيقول إن هو نفسه العزيز ولما يرجع للمدينة هيخرج رسول الله ﷺ ذليلا، عليه من الله ما يستحق رأس المنافقين ده\nوسط المنافقين إللي قاعدين دول كلهم كان في شاب صغير مؤمن اسمه زيد بن أرقم سامع الحوار ده كله،\nغضب زيد رضي الله عنه لرسول الله ﷺ وإنه إزاي يتقال عليه وعلى الصحابة كده، بس هو مش في إيده يعمل حاجة،\nفراح لرسول الله ﷺ وقال له على إللي حصل كله، وكان رسول الله ﷺ قاعد مع مجموعة من أصحابه وكان فيهم عمر،\nفقال عمر لرسول الله ﷺ: سيبني يا رسول أضرب عنق المنافق ده\nفهدأه رسول الله ﷺ، وقال له : اتركه لا يتحدث الناس أن محمدا يقتل أصحابه\nوصل الخبر لعبد الله بن أبي بن سلول إن زيد بن أرقم حكى لرسول الله ﷺ إللي حصل، فجاء عبد الله بن أبي لرسول الله ﷺ وقال له:\nوالله ما قلت ولا اتكلمت يا رسول الله \n \nفقال بعض الأنصار من إللي كانوا قاعدين يمكن زيد سمع غلط أو فهم غلط ومحفظش الكلام إللي اتقال\nطبعا الموقف كله في صالح عبد الله بن أبي بن سلول \nمين إللي يصدق شاب صغير عنده ستة عشرة سنة ويكذّب عبد الله بن أبي بن سلول سيد القوم إللي كان هيكون ملك على المدينة وكمان حلف بالله،\nومفيش أي دليل يقدر زيد بن أرقم يقدمه، ولا إنه يجيب حد يشهد معاه لأن كل إللي كانوا موجودين ساعتها كانوا من المنافقين،\nوزيد قعد يدافع ويقول والله قال، لكن محدش سمع له وصدقوا عبد الله بن أبي بن سلول،\nواغتم زيد بن أرقم جدا وعمه قال له : انت معملتش حاجة غير إنك خليت رسول الله ﷺ يكرهك\nرسول الله ﷺ عرف إن الموضوع ده مش هيعدي وهيعمل أزمة فعشان الناس متنشغلش بالكلام في الموضوع ده وتحصل فتنة، أمر المسلمين إنهم يتحركوا عشان يرجعوا للمدينة، \nلكن الوقت إللي أمرهم يتحركوا فيه مكنش الوقت إللي متعودين يتحركوا فيه، \nفقابل أسيد بن حضير رسول الله ﷺ وقال له : إيه إللي حصل يا رسول الله، أول مرة نتحرك في الوقت ده\nفقال له رسول الله ﷺ:\nانت معرفتش صاحبك قال إيه؟!\nفقال أسيد :\nأنهو صاحب يا رسول الله \nقال له رسول الله ﷺ: عبد الله بن أبي، قال لما يرجع للمدينة هيخرج الأعز منها الأذل!\nفقال له أسيد :\nفأنت يا رسول الأعز\nلو انت عايز والله لنخرجه من المدينة ذليل وانت العزيز\nمعلش يا رسول الله خليك رحيم معاه، انت جئتنا وقومه كانوا بيصنعوا له التاج، فهو شايف إنك خدت منه ملكه\nمشي رسول الله ﷺ بالناس يوم كامل حتى بالليل فضلوا ماشيين مستريحوش،\nوتاني يوم فضلوا ماشيين برده لحد ما الشمس آذتهم فأمر رسول الله ﷺ الناس إنهم يرتاحوا،\nوأول ماقعدوا يريحوا راحوا نايمين كلهم وهو ده إللي رسول الله ﷺ كان عايزه،\nإن ميبقاش في وقت للناس يقعدوا يتكلموا فيه\nهل الموضوع وقف على كده، وإيه إللي هيحصل لزيد بن أرقم، ده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 129, "l": "الجزء 103 | احداث السنة السادسه من الهجره | حادثة الإفك", "u": "https://www.facebook.com/groups/710210019782034/permalink/820568175412884/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة\n#أحداث_السنة_السادسة_من_الهجرة\n#حادثة_الإفك\nاتكلمنا المرة إللي فاتت عن إللي حصل مع زيد بن أرقم وإن عبد الله بن أبي بن سلول أنكر الكلام إللي قاله،\nوشوفنا إزاي رسول الله ﷺ اتعامل بحكمة مع الموقف عشان ميديش المجال للناس إنهم يتكلموا في الموضوع،\nكمل رسول الله ﷺ طريقه للمدينة وقبل ما يوصل للمدينة بقليل نزلت الآيات بتصديق زيد بن أرقم وفضح كذب المنافقين،\nزيد بن أرقم كان راكب على دابته وماشي مع الجيش، وكان موطي رأسه من الهم،\nفجاءه رسول الله ﷺ ومسك أذنه وضحك وقال له :\nإن الله قد صدّقك\nيعني ربنا أنزل آيات تؤكد الكلام إللي انت قلته،\nوأرسل رسول الله ﷺ في طلب عبد الله بن أبي بن سلول وإللي كانوا معاه، وقرأ رسول الله ﷺ الآيات من سورة المنافقين على الناس وعلى المنافقين:\n\"هُمُ الَّذِينَ يَقُولُونَ لَا تُنفِقُوا عَلَىٰ مَنْ عِندَ رَسُولِ اللَّهِ حَتَّىٰ يَنفَضُّوا\"\n\"يَقُولُونَ لَئِن رَّجَعْنَا إِلَى الْمَدِينَةِ لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ\"\nففرح زيد جدا بتصديق ربنا له\nوكان رسول الله ﷺ يمسك أذن زيد ويقول:\nهذا الذي أوفى الله بأذنه!\nواتفضح المنافقين وعلى رأسهم عبد الله بن أبي بن سلول \nالناس قالوا بس، دي نهاية عبد الله بن أبي بن سلول وأصحابه، أكيد رسول الله ﷺ هيقتلهم،\nفوصل لعبد الله بن عبد الله بن أبي بن سلول كل إللي حصل من أبوه وكلام الناس إن رسول الله ﷺ خلاص هيقتله وكان عبد الله ده مؤمن صادق الإيمان، \nفذهب لرسول الله ﷺ وقال له:\nيا رسول الله! أنا عرفت إنك عايز تقتل أبي، والعرب كلهم عارفين إن مفيش حد أبر بأبوه مني، \nفلو عايز تقتله أُأمرني أنا أقتله، لأني أخاف إنك تأمر حد تاني يقتله، وأشوف قاتل أبي يمشي بين الناس عادي فمقدرش اصبر واستحمل فأقتله ويبقى كده قتلت رجل مسلم مقابل رجل كافر فأدخل النار \n☆عبد الله بن عبد الله بن أبي بن سلول معندوش أي مانع إنه يقتل أباه المنافق، وده مش أي ابن ده ابن بار جدا بأبوه لكن بره بأبوه ممنعهوش إنه ينصر دين ربنا ويقف مع الحق حتى لو هيضحي بأبوه،\nفالله ورسوله أهم عنده من أي حد تاني.\nرسول الله ﷺ قال له : لأ مش هنقتله وهنترفق به ونحسن إليه \nولما رسول الله ﷺ عفا عن عبد الله بن أبي بن سلول قبيلته وجماعته بقوا هم إللي يعاتبوه ويعنفوه ومبقاش له ناصر ينصره، فقال رسول الله ﷺ لعمر بن الخطاب رضي الله عنه وكان عايز يقتله:\nكيف تري يا عمر؟! أما والله لو قتلته يوم قلت أقتله لأرعدت له أنوف لو أمرتها اليوم بقتله لقتلته\nيعني رسول الله ﷺ بيقوله شوفت، لو كنت أمرت بقتله يوم ما قلت لي أقتله لاعترض الناس وأخذتهم الحمية لزعيمهم وقتها، ولو النهاردة أمرتهم بقتله لقتلوه،\n فقال عمر : أنا عرفت والله إن رأي رسول الله ﷺ أعم بركة من رأيي!\nتقدم عبد الله بن عبد الله بن أبي بن سلول ووقف عند مدخل المدينة ومعاه سيفه، ودخل رسول الله ﷺ المدينة ودخل الصحابة ولما جاء أبوه عبد الله بن أبي بن سلول يدخل منعه ابنه عبد الله وقال له:\nوالله لا تدخلها حتى يأذن رسول الله ﷺ فهو الأعز وأنت الأذل، ومش هسيبك غير لما تقول عن نفسك إن انت الأذل ورسول الله ﷺ هو الأعز\nطبعا عبد الله بن أبي بن سلول واقف مصدوم إزاي ابنه البار ده يقول له الكلام القاسي الشديد ده وفي وسط الناس الكلام ده، يعني ذل ما بعده ذل\nفأذِن له رسول الله ﷺ بدخول المدينة وقال عبد الله بن أبي بن سلول عن نفسه إن هو الأذل ورسول الله ﷺ هو الأعز.\nإللي حصل ده كله خلى عبد الله بن أبي بن سلول والمنافقين معاه بيغلوا من الغيظ وعايزين ينتقموا من رسول الله ﷺ،\nمع إن هم إللي غلطانين في الأصل وهم أصلا سبب الأزمة،\nبس هم مش شايفين كده\nأمثال عبد الله بن أبي بن سلول ده موجودين معانا في حياتنا وبنشوفهم وبنتعامل معاهم على طول، والناس دي محدش سلم منها حتى رسول الله ﷺ فنتبع منهج رسول الله ﷺ في التعامل معاهم عشان نتجنب ونقلل أذاهم وضررهم بقدر الإمكان\nفي الوقت إللي حصل فيه أحداث عبد الله بن أبي بن سلول كان في أحداث تانية بتحصل في مكان تاني،\nهنرجع بالزمن شوية للوراء قبل ما جيش المسلمين يوصل للمدينة، \nكان رسول الله ﷺ وقف بالجيش عشان يرتاحوا،\nوكانت النساء في جيش المسلمين بيركبوا على الجمال في الهَوْدَج، والهودج ده زي خيمة صغيرة بتتحط فوق الجمل وقت السفر،\nولما يقعدوا يريحوا بيشيلوا الهودج وينزلوه في الأرض وتفضل النساء قاعدة جواه،\nالسيدة عائشة خرجت من الهودج بتاعها ومشيت بعيد عن الجيش من غير ما حد يعرف لقضاء الحاجة،\nفلما خلصت ورجعت وضعت إيدها على صدرها ملقتش العقد بتاعها، وقع منها تاني \nفراحت تدور عليه في المكان إللي كانت فيه، في الوقت ده كان رسول الله ﷺ أمر الناس بالتحرك، فجاء الرجال وحملوا الهودج بتاع عائشة ووضعوه فوق الجمل ومشيوا،\nوعائشة رضي الله عنها في الوقت ده كانت لسه مكملتش خمسة عشرة سنة وكانت رفيعة فالهودج أصلا كان خفيف حتى وهي قاعدة فيه، فلما شالوا الهودج وهي مش موجودة فيه محسوش بفرق ومعرفوش إن السيدة عائشة مش موجودة فيه،\nالسيدة عائشة لقت العقد بتاعها ورجعت ملقتش الجيش، ولقت نفسها في صحراء لوحدها\nفقالت هقعد في نفس المكان بتاعي وهم لما يفتقدوني ويعرفوا إني مش موجودة هيرجعوا يدوروا عليّ\nقعدت السيدة عائشة في مكانها وبما إنها لوحدها في الصحراء فكشفت عن وجهها عشان تبقى براحتها، ومن التعب راحت في النوم،\nرسول الله ﷺ كان من عادته إنه يجعل رجل في آخر الجيش عشان لو حاجة سقطت من المسلمين يأخذها ويرجعها لهم،\nأو مثلا حد تعب يساعده، وفي أوقات كان رسول الله ﷺ بنفسه بيتولى المسؤولية دي على حسب الموقف، \nفالمرة دي كان رسول الله ﷺ متقدم مع الجيش لأنه كان مشغول بقضية عبد الله بن أبي بن سلول والأحداث إللي حصلت مع المنافقين،\nفجعل رسول الله ﷺ المسؤولية دي لواحد من الصحابة اسمه صفوان بن المُعَطّل،\nولعل السبب إن رسول الله ﷺ جعل المهمة دي لصفوان بالذات؛ لأن صفوان كان نومه ثقيل بيصحى بصعوبة فكان بيتأخر عن باقي الجيش فبقت له المهمة دي،\nالمهم، صفوان ماشي عشان يلحق الجيش شاف سواد إنسان من بعيد، فاستغرب مين إللي في الصحراء لوحده ده\nفقرب لقاها عائشة رضي الله عنها وهي نائمة، وكانت ساعتها كاشفة عن وجهها فعرفها لأنه كان بيشوفها قبل الحجاب، والحجاب لسه مفروض من كم شهر فقط، \nفأول ما شافها قال :\nعائشة، زوجة رسول الله ﷺ \nإنا لله وإنا إليه راجعون \nفسمعت صوته عائشة رضي الله عنها وصحيت من النوم وراحت مغطية وجهها على طول، ومردتش عليه بكلمة وهو كمان مكلمهاش ولا كلمة، وراح مقعّد البعير في الأرض وفضل ماسكه وهو مدي ظهره لعائشة عشان ميشوفهاش،\nفقامت عائشة رضي الله عنها وركبت على البعير، ومسك صفوان حبل البعير ومشي بيه ومتكلمش مع عائشة رضي الله عنها ولا كلمة ولا حتى نظر إليها إجلالا لعرض النبي ﷺ، واحنا قلنا قبل كده إن الصحابة من بعد آية الحجاب لم ينظروا لزوجات رسول الله ﷺ، \nوصلوا المدينة وكان وقت الظهر بعد ما حصلت الأزمة مع المنافقين على طول، الناس اتفاجئت بعائشة داخلة مع صفوان مع إنها المفروض كانت في الهودج،\nالقلوب السليمة هتفكر إن ده موقف عادي جدا ممكن يحصل لأي أحد، وزوجة رسول الله ﷺ إللي ربنا اختارها له زوجة في الدنيا والآخرة مستحيل هيقع منها شيء يطعن في شرفها،\nأصحاب القلوب الخبيثة المريضة وعلى رأسهم زعيم المنافقين عبد الله بن أبي بن سلول وكان ساعتها بيغلي من الغيظ وعايز ينتقم من رسول الله ﷺ ويطعن فيه، مصدق شاف الموقف ده، فبعد ما مشي صفوان مع عائشة قال بكل حقد وخبث : \nزوجة نبيكم باتت مع صفوان لحد الصبح\nوالله ما نجا منها ولا نجت منه\nخدوا بالكم إنه هو عرّض بالكلام، مصرحش وقال إن السيدة عائشة فعلت الفاحشة\nومسكتش بقى ده قعد ينشر الموضوع بين الناس ويذيعه ويعيد ويزيد فيه والمنافقين معاه شغالين في إشاعة الخبر بين الناس،\nووقع بعض الصحابة صادقي الإيمان في إنهم يصرحوا إن السيدة عائشة وقعت فعلا في الفاحشة،\nواللئيم ده نفسه مصرحش بكده\nوالناس مبقاش وراهم كلام غير موضوع عائشة وصفوان رضي الله عنهما، \nوالمدينة اتقلبت والوحي انقطع وقلوب الناس اتهزت وإللي بيتكلم يتكلم وإللي يدافع يدافع، \nوالمنافقين مش ساكتين عمالين يولعوا الدنيا أكثر، وكل ده ورسول الله ﷺ مش قادر يعمل أي حاجة\nمش قادر يدافع عن زوجته، مش قادر يدافع عن أحب الناس إليه، ومفيش وحي يأكد أو ينفي الكلام ده،\nالزنا يا جماعة من أقبح الجرائم، تخيلوا إن الكفر جريمته أعظم من الزنا بس مفيش حد بيُعيّر إنه كافر أو إن أحد من أهله كافر، لكن الزنا لأ، الزنا عار ،\nعشان كده ربنا حمى كل الأنبياء من وقوع أي حد من أهل بيوتهم في الزنا، \nوالزنا عند العرب كان حاجة عظيمة جدا،  وكان معروف إن الحرة لا تزني وإن الأمة بس هي إللي ممكن تقع في الزنا،\nوكمان امرأة متزوجة، فكان الموضوع كبير جدا ومش سهل لا على المسلمين ولا حتى على رسول الله ﷺ،\nومينفعش رسول الله ﷺ يطلع كده بين الناس يقول إن عائشة بريئة والكلام إللي بيتقال عليها ده غلط،\nلأن محمد بن عبد الله رسول من عند الله لا ينطق عن الهوى،\nمينفعش يقول أي حاجة كده بدون دليل أو وحي من الله،\nكل حاجة بيعملها؛ الناس بتقلده فيها بعدين،\nفكل خطوة وكل كلمة محسوبة لا يملك من أمره شيء، فتخيلوا ساعتها إحساسه كان عامل إزاي، وحتى مجرد الدفاع عن زوجته إللي بيحبها ومتأكد إنها بريئة مش بإيده\nيا جماعة احنا لو حد اتكلم علينا بكلمة بسيطة بنبقى هنتجنن ونقوّم الدنيا وإزاي يتقال الكلام ده ونتخانق ونعمل ونسوي، \nالناس قعدوا يتكلموا عن السيدة عائشة شهر كااامل، ومش كلام عادي ده في ناس صرحوا كده وش كده وقالوا إنها فعلت الفاحشة \nوكل ده ورسول الله ﷺ بيوصله الكلام، كل يوم طعنة جديدة في قلبه ومش قادر يعمل حاجة، ومفيش وحي\nالسيدة عائشة بقى في وسط  كل ده مكنتش تعرف حاجة نهائي عن الموضوع\nبعد ما وصلت المدينة مرضت مرض شديد جدا لدرجة إنها مكنتش تقدر تتحرك من السرير، \n☆أنا شخصيا بعتبر مرضها ده من رحمة ربنا ولطف بها\nلأن السيدة عائشة مكنتش هتستحمل الضغط النفسي الشديد مدة شهر كامل، \nفمرضها خلاها مشغولة بنفسها وخلى إللي حواليها يخبوا عليها عشان حالتها متبقاش أسوأ وبكده يبقى الموضوع أخف عليها لما تعرف متأخر من إنها تعرف من بداية الموضوع خالص وتفضل عايشة في الضغط النفسي ده وهي صغيرة في السن،\nوهنشوف أصلا رد فعلها هيبقى عامل إزاي لما تعرف\nكلام الناس وصل لصفوان بن المعطل فغضب صفوان وقال:\nسبحان الله! والله ما كشفت كَنَف أنثى قط\nيعني لم يجامع امرأة أبدا، فعلى الرغم من إنه كان شاب فحتى في الجاهلية قبل إسلامه لم يفعل ما كان يفعله الشباب ومكنش لسه تزوج.\nرسول الله ﷺ بدأ يتحرّى عشان يجمع الأدلة ويشوف فعلا هل الكلام ده له أساس من الصحة ولّا لأ\nوركزوا بقى عشان إللي رسول الله ﷺ هيعمله ده دين لازم نتبعه فيه لو حصل معانا موقف زي كده،\nيعني لو وصلنا عن حد كلام أو إنه عمل حاجة وحشة سواء قريب ولا بعيد متاخدناش الحمية ونتصرف غلط وبعدين نعقد الموضوع أكثر\nرسول الله ﷺ مرحش واجه عائشة رضي الله عنها ولا كلمها خااالص، راح الأول سأل الناس إللي لهم علاقة بيها يمكن يكونوا شافوا حاجة، يعني دوّر على دليل ،فسأل زوجته زينب بنت جحش فقالت:\nأصون سمعي وبصري يا رسول الله، والله لم أعلم عن عائشة إلا خيرا\nوزينب كانت منزلتها قريبة جدا من منزلة عائشة في قلب رسول الله ﷺ، يعني دي كانت فرصتها، \nيعني حتى كانت ممكن تلمح بالكلام وخصوصا إن اختها حَمْنة بنت جحش كانت من الناس إللي صرحت بإن عائشة وقعت فعلا في الفاحشة، \nلكن زينب رضي الله عنها عصمها الورع وتقواها من إنها تقول أي كلام في حق السيدة عائشة رضي الله عنهما،\nرسول الله ﷺ استشار أسامة بن زيد بن حارثة وعلي بن أبي طالب يعمل إيه، \nوطبعا مش هينفع يستشير أبو بكر الصديق لأنه أبوها والموضوع فيه حساسية، وكمان مش هيعرف يستشير عمر بن الخطاب رضي الله عنه لأن رسول الله ﷺ متزوج من حفصة بنته\nفلما سأل أسامة بن زيد قال له أسامة:\nيا رسول الله! أهلك وانت أدرى بيهم واحنا منعرفش عنهم إلا خيرا\nعلي بن أبي طالب رضي الله عنه قال له:\nيا رسول الله! النساء غيرها كثير، وربنا لم يضيق عليك،\nولو انت مش عايز تفارقها، خلاص اسأل الجارية وهي هتقولك\n☆الصحابة يا جماعة كانوا بيحبوا رسول الله ﷺ حب فوق الوصف، فكان يعز عليهم جدا إنهم يشوفوا رسول الله ﷺ زعلان أو متضايق، وده مكنش أي زعل، \nرسول الله ﷺ كان أغير الناس فتخيلوا لما زوجته يتقال عليها الكلام ده هتبقى نفسيته عاملة إزاي، دي أزمة مش سهلة أبدا\nفعلي بن أبي طالب اقترح عليه إنه يطلق عائشة عشان يستريح نفسيا لحد ما الوحي ينزل يأكد له براءتها وبعدين يرجعها تاني، \nوالاقتراح التاني كان إنه يسأل بريرة مولاة عائشة عنها، لأن الخادمة هي أكثر واحدة قاعدة معاها وشايفة كل تحركاتها ولو في أي حاجة فيها ريبة هتلاحظها\nأحضروا بَرِيرة مولاة عائشة، وقعدوا يسألوها عنها، فقالت لهم بريرة : \nعيب عائشة الوحيد إنها صغيرة في السن فبتنام وتسيب العجين وتيجي الفراخ وتأكله، غير كده معرفش عنها إلا خيرا\nفعلي بن أبي طالب قعد يضغط عليها عشان تقول الحقيقة لدرجة إنه ضربها عشان لو مخبية حاجة تقولها،\nفمغيّرتش من كلامها وكان علي رضي الله عنه عايز يُطمئِن قلب رسول الله ﷺ لما يسمع من بريرة إن مفيش أي شائبة على عائشة، رضي الله عنها،\nرسول الله ﷺ كان متأكد من براءة عائشة لكن مكنش معاه دليل مادي ولا معاه وحي يقدر يجزم بيه ببراءة عائشة\nاحنا بنتعامل مع مجتمع كامل منتشر فيه الإشاعة دي،\nمش حاجة بين زوجين مثلا فنقدر نعديها بالثقة، لأ، ده لازم حاجة قوية جدا تسكت الناس دي وميبقاش في أي مجال للكلام بعد كده،\nلكن الحاجة دي لسه مش في إيد رسول الله ﷺ والناس عمالة تتكلم\nرسول الله ﷺ جمع المسلمين عشان يحاول يدافع عن السيدة عائشة ويهدّي الدنيا شوية ويقلل من كلام الناس،\nيا ترى قالهم إيه، وهل اقتنعوا بكلامه ولّا الأمور اتأزمت أكثر، ده إللي هنعرفه الجزء الجاي إن شاء الله \n☆"}, {"n": 130, "l": "الجزء 104 | احداث السنة السادسه من الهجره | البرائه من الإفك", "u": "https://www.facebook.com/groups/710210019782034/permalink/821142285355473/", "t": "برائة السيده عائشه \n واخيرآ نزل الوحي\n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة\n#أحداث_السنة_السادسة_من_الهجرة\n#البراءة_من_الإفك\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما خرج للناس عشان يكلمهم ويحاول يهديهم شوية ويسكتهم،\nفوقف وسط المسلمين وبدأ يخطب فيهم وقال:\nيا معشر المسلمين، من يعذُرني من رجل قد بلغني عنه أذاه في أهلي، ووالله ما علمت على أهلي إلا خيرا، \nولقد ذكروا رجلا ما علمت عليه إلا خيرا وما يدخل على أهلي إلا معي\nيعني رسول الله ﷺ بيقول للمسلمين مين ينصفني أو ياخد حقي من رجل بيقول على زوجتي كلام سيء ونشر الكلام ده بين الناس، وزوجتي متزوجها من سنين ومشفتش منها إلا كل خير،\nوحتى الرجل إللي بيتكلموا عنه بالكلام الفاحش ما عرفتش عنه إلا كل خير، \nولما كان بيدخل بيتي مكنش بيدخل إلا وهو معايا فمفيش مجال لأي علاقة بينه وبين زوجتي فإزاي هتحصل الفاحشة بين اتنين مفيش بينهم حتى كلام،\nفقام أُسَيد بن حضير سيد الأوس وقال لرسول الله ﷺ:\nأنا أعذرك منه يا رسول الله، يعني أنا أخد لك حقك منه،\nإن كان من الأوس ضربت عنقه، وإن كان من إخواننا من الخزرج، أُأمرنا واحنا هننفذ أمرك على طول \n☆واخدين بالكم إن رسول الله ﷺ مأنكرش على أُسيد بن حضير موضوع القتل، لأن من يؤذي رسول الله ﷺ حده القتل\nواحنا اتكلمنا قبل كده في الجزء الواحد والعشرين لو تفتكروا عن حكم من يشتم رسول الله ﷺ وقلنا إن حده القتل حتى لو تاب،\nسعد بن عبادة سيد الخزرج سمع إللي قاله أُسيد بن حضير فاتضايق وغضب وأخذته الحمية إزاي يتقال على واحد من قبيلته كده وقال:\nانت غلطان ، متقدرش تقتله ولو كان من قومك مكنتش هتحب يتقال عليه الكلام ده\nفرد عليه أسيد وقال :\nإنت إللي غلطان والله لنقتله، وانت منافق تجادل عن المنافقين\n☆سعد بن عبادة كان صحابي صادق الإيمان، لكن أخذته العصبية إن إزاي الأوس يكون لهم الفضل والفخر ويبقوا أحسن منهم قصاد رسول الله ﷺ، وهم كانوا لسه من كم سنة بس الحروب شغالة بينهم،\nفكأن الأوس غلبتهم في الفضل وإن واحد من قبيلة سعد هو إللي سبب في الأزمة دي، فاتضايق سعد بن عبادة وبدأ يقول الكلام ده،\nوأسيد غضب لرسول الله ﷺ إزاي سعد بن عبادة يدافع واحد منافق، خلاص يبقى انت كمان منافق زيه عشان كده بتدافع عنه،\nطبعا قبيلة ده اتعصبت وقبيلة ده اتعصبت راحوا قايمين على بعض ومعاهم السيوف وهيقتتلوا وهتبقى حرب أهلية\n والكلام ده كله بيحصل قصاد رسول الله ﷺ وهو واقف على المنبر وشايف إللي بيحصل،\nمتخيلين إحساس رسول الله ﷺ في الوقت ده وهو بيشوف بعينه الناس إللي رباهم وعلمهم وخرجوا معاه في الجهاد وضحك معاهم وأكل معاهم هيقتلوا بعض\nوكل ده بسبب كلمة اتقالت والناس قعدت تنقل الكلام من هنا لهنا من غير ما يفكروا في العواقب،\nرسول الله ﷺ كان عايز يه يحل الموضوع بأي طريقة لكن للأسف الأمور اتعقدت أكثر،\nقعد يسكّت فيهم ويهديهم لحد ما سكتوا وسكت رسول الله ﷺ عشان متحصلش حرب بينهم، والمستفيد طبعا من الموضوع ده المنافقين وكل أعداء المسلمين،\nيعني الواحد متخيل شكل عبد الله بن أبي بن سلول وهو بيبتسم في خُبث وفرح لما شاف الوقيعة إللي حصلت بين الصحابة وإنه حقق هدفه، عليه لعنة الله\nكل ده والناس عمالة تتكلم، واحد من الصحابة اسمه أبو أيوب الأنصاري، لو تفتكروه هو إللي رسول الله ﷺ قعد في بيته لما هاجر للمدينة وكان بيته من دورين وحصلت القصة إللي اتكلمنا عليها في الجزء التاسع والأربعين،\nالمهم زوجة أبو أيوب بتقول له:\nسمعت الناس بيقولوا إيه على عائشة وصفوان\nفقال لها أبو أيوب الأنصاري رضي الله عنه:\nيا أم أيوب! لو انتِ كنتِ مكان عائشة كنتي هتعملي إللي الناس قالوا عليه ده\nفقالت له : لأ طبعا\nفقال لها : وأنا لو مكان صفوان مكنتش هعمل إللي الناس بتقول عليه، فكيف وعائشة أحسن منك وصفوان أحسن مني\nيعني احنا أهه عمرنا ما نعمل كده، عائشة وصفوان أحسن مننا احنا الاتنين فمستحيل يعملوا حاجة زي كده،\n☆وهنا لازم نقف ونفهم معنى مهم جدا، وهو معنى حسن الظن\nانتم عارفين ليه بنقع في سوء الظن، بنقع في سوء الظن لأننا بنعامل الناس بشخصيتنا احنا، يعني لو أنا اتحطيت في الموقف الفلاني هيكون تصرفي كذا، \nفبتخيل بقى إن أي حد هيكون في الموقف ده هيتصرف نفس تصرفي وبتبقى حاجة تلقائية على فكرة ومش بناخد بالنا خالص\nوزي ما قيل:\nكل إنسان يرى الناس بعين طِبْعِه\nفاحنا لو أصلحنا من نفسنا هنتخلص من سوء الظن، \nلأن فُضلاء المؤمنين والمؤمنات لما يقيسوا الأمور على أنفسهم ، ويلاقوا إنهم ميعملوش الحاجة دي هيفكروا إن غيرهم ميعملش كده،\nوخصوصا لو كان غيرهم مكانتهم أعلى وأفضل منهم،\nوالعكس صحيح، يعني لو واحد شخصيته سيئة وقلبه مريض هتلاقيه بيتهم الناس اتهامات مش فيهم،\nمثلا يعني لما نيجي ننصح حد ويبقى فعلا نيتنا النصيحة، مش ساعات الشخص إللي بننصحه ياخد الكلام ويعمل عليه مشكلة ويقعد يقول بصوا لنفسكم الأول \nهو انتم مش وراكم غير النقد، وانتم هتعملوا فيها شيوخ وانتم بتتكبروا علينا و...و...\nعارفين الناس دي بتاخد الكلام على إنه انتقاد وتكبر ليه\nلأنهم لو كانوا في نفس الموقف هتكون نيتهم وقصدهم التكبر والانتقاد،\nوعلى فكرة مفيش فرق كبير بين النقد والنصيحة، لكن الموضوع بيعتمد أكثر على الشخص إللي بيستقبل الكلام هياخده بأي طريقة\nهو لو عايز ياخده نصيحة هياخده نصيحة، ولو مش عايز هتلاقوه بيطلع أي سبب عشان يجيب الغلط على الطرف إللي بينصحه\nفاحنا بس مسؤولين عن الكلام إللي بيخرج مننا، هل الكلام سيء ولّا لأ، ساعتها لو كلامنا سيء يبقى الغلط علينا فعلا\nوعارفين كمان هتلاقوا الناس الطيبة إللي على طول نيتهم حسنة هم أكثر ناس بيقعوا في مشاكل؛ لأنهم بيظنوا إن الناس زيهم فيتعاملوا بطيبة قلبهم \nطب احنا نعمل إيه بقى،\nمينفعش نُسيء الظن بالناس، وفي نفس الوقت لو اتعاملنا بطيبة وحسن نية هنقع في مشاكل يبقى الحل إيه هنا\nالحل بسيط: إن يبقى عندنا حسن الظن وحسن النية لكن مع الحذر\nيعني لما بنتعامل مع الناس بنحسن الظن فيهم ومنحكمش عليهم من وجهة نظرنا وفي نفس الوقت نكون على حذر منهم، يعني يبقى في مسافة كده بيننا وبينهم،\nعارفين حرف ال H... شايفين المسافة إللي في النص دي،\nهي دي المسافة المطلوبة في علاقتنا مع الناس حتى القريبين مننا، طول ما احنا سايبين المسافة دي مش هتحصل معانا أي مشاكل\nشوفتم موقف أبو أيوب الأنصاري والكلام إللي أنا قلته ده ربنا لخصه لنا في آية :\n\"لَوْلا إِذْ سَمِعْتُمُوهُ ظَنَّ الْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بِأَنْفُسِهِمْ خَيْرًا \"\nشوفتم كلمة 《بأنفسهم》 دي، أهه هي دي إللي بنتكلم فيها من الصبح، يعني انتم بتتكلموا عن أنفسكم قبل ما تتكلموا عن غيركم، \nوانتم بتعكسوا مرآة صدوركم لما تتكلموا عن غيركم،\nفلو أصلحنا نفسنا هيبقى سهل أوي إننا نحسن الظن في الناس، \nلما نضع نفسنا مكان الناس ونقول أنا مستحيل أعمل كده، يبقى غيري برده زيي، وخصوصا إللي أنا عارف عنه إنه أحسن مني مستحيل يعمل كده\nكل الأحداث إللي حاصلة في المدينة دي السيدة عائشة مريضة ومتعرفش عنها حاجة، \nوالوضع استمر كده حوالي شهر، لحد ما في يوم السيدة عائشة حالتها اتحسنت شوية وخرجت مع أم مِسْطح ناحية المنَاصع، \nوهو المكان إللي النساء كانت بتخرج فيه لقضاء الحاجة.\n☆وهنا في فائدة مهمة، وهي إن المرأة لما تيجي تخرج تاخد حد معاها، وخصوصا لو بالليل وفي مكان يعتبر ساكت مفهوش حد\nأم مسطح دي تبقى بنت خالة أبو بكر الصديق رضي الله عنه، وهم راجعين أم مسطح اتكعبلت في العبائة بتاعتها،\nفقالت : تَعِس مِسطح \nبتدعي على ابنها يعني، فالسيدة عائشة قالت لها: \nإيه إللي بتقوليه ده، بتشتمي رجل حضر غزوة بدر\n☆وكان إللي حضر غزوة بدر ده له مكانة خاصة بين الناس وحتى عند الله، وجبريل عليه السلام جاء إلى رسول الله ﷺ  وقال له :\nما تعدّون أهل بدر فيكم ؟ قال رسول الله ﷺ : من أفضل المسلمين ! فقال جبريل : وكذلك من شهد بدرا من الملائكة\n وقال رسول الله ﷺ في حديث تاني:\n\" لَعَلَّ اللَّهَ عزَّ وجلَّ اطَّلَعَ علَى أهْلِ بَدْرٍ فَقالَ: اعْمَلُوا ما شِئْتُمْ فقَدْ غَفَرْتُ لَكُمْ\"\nيعني ربنا جعل لأهل بدر المكانة العالية دي، لكن طبعا مش في الحدود، لو حصل حاجة فيها حد لازم يحصل القصاص زي ما هنشوف إللي حصل مع مِسطح\nفأم مِسطح قالت لعائشة:\nهو انتِ يابنتي متعرفيش قال إيه عنك\nفقالت لها عائشة رضي الله عنها: قال إيه\nفحكت لها أم مسطح عن الكلام إللي مسطح قاله وإنها فعلت الفاحشة وإن الناس بتتكلم عنها،\nطبعا السيدة عائشة اتصدمت ومرضها زاد عليها، وعرفت السبب في المعاملة الغريبة إللي كان رسول الله ﷺ بيعاملها لها،\nيعني رسول الله ﷺ كان دايما بيعاملها بلطف، وخصوصا لما تكون مريضة بيتلطف معاها زيادة، لكن المرة دي مكنش بيعمل كده، كان لما يدخل عليها كان يسلم ويسأل أمها عنها: كيف تِيكم؟ يعني كيف هذه، وبعدين يمشي،\nفكانت مستغربة من معاملته لها لكن محستش بأي حاجة وإن في مشكلة ولا في شر،\nفلما رجعت للبيت بعد ما عرفت الخبر من أم مسطح دخل عليها رسول الله ﷺ وسأل عنها زي ما بيسأل كل مرة،\nفطلبت عائشة من رسول الله ﷺ إنها تروح تزور أبويها ، فأذن لها رسول الله ﷺ،\nهي كانت عايزة تتأكد من الموضوع، هل فعلا الكلام إللي سمعته ده حقيقي ولّا لأ،\nومش هينفع تسأل رسول الله ﷺ لأن الموضوع حساس وهو لحد دلوقتي متكلمش، يبقى هو مش عايز يتكلم، يبقى تشوف حد تاني تتأكد منه،\nفراحت فعلا بيت أبوها ابو بكر الصديق رضي الله عنه وسألت أمها: \nهم الناس بيقولوا إيه\nفأمها قالت لها: هوني عليكِ....متزعليش نفسك، ده نادر جدا لما تكون امرأة جميلة عند رجل بيحبها ولها ضرائر والناس تسيبها في حالها\nفقالت لها عائشة : \nوالناس اتكلمت في الموضوع والكلام وصل لرسول الله ﷺ \nفقالت لها أمها : نعم\nهنا بقى السيدة عائشة زي ما بنقول بلغة عصرنا انهارت\nوفي رواية بتقول إنها أُغْمي عليها والحمى ارتفعت عليها،\nوقعدت تبكي طول الليل لحد الصبح، وقعدت تبكي يوم كامل وقعدت تبكي الليلة إللي بعدها،\nيعني ليلتين ويوم وهي بتبكي ومقهورة ومفيش نوم خالص، وأبواها قاعدين معاها مش قادرين ولا عارفين يعملوا حاجة وخايفين عليها لتموت بسبب البكاء إللي كانت بتبكيه\n☆شوفتم رحمة ربنا ولطفه بيها، تخيلوا لو مكنتش مريضة وكانت عرفت من أول الشهر كان زمان حصل لها إيه\nوهمّ على الحالة دي استأذنت على السيدة عائشة امرأة من الأنصار فأذنت لها عائشة فدخلت وقعدت تبكي مع عائشة وكأنها بتواسيها في مصيبتها،\nوهم كلهم قاعدين كده دخل عليهم رسول الله ﷺ فسلم وجلس، ودي كانت أول مرة رسول الله ﷺ يقعد عند السيدة عائشة من ساعة ما بدأ الناس يتكلموا، يعني بقاله شهر ،\nتشهّد رسول الله ﷺ وقال: \nأما بعد، أنا بلغني عنك يا عائشة كذا وكذا، فإن كنتِ بريئة، ربنا هيبرئك، ولو كنتِ عملتِ ذنب فاستغفري الله وتوبي إليه، فإن العبد إذا اعترف بالذنب ثم تاب، ربنا بيتوب عليه \n☆إيه ده\nمعنى كلام رسول الله ﷺ إنه شك في عائشة رضي الله عنها إنها وقعت في الفاحشة\nكبداية كده، رسول الله ﷺ لم يظن أبدا إن عائشة رضي الله عنها وقعت في الفاحشة،\nولما قال لها إن كنتِ فعلتي ذنب فاستغفري الله، كان يقصد وقوعها في الصغائر مش إنها فعلت الفاحشة يعني بيتكلم بصيغة العموم\nفرسول الله ﷺ لم يشك أبدا في عائشة وكان يعلم براءتها،\nلأنه عارف عائشة رضي الله عنها كويس، \nوكمان عارف إن نساء الأنبياء بصفة عامة ربنا حافظهن من الوقوع في الفاحشة، \nخدوا بالكم مش عصمة، يعني نساء الأنبياء مش معصومات من الوقوع في الفاحشة؛ لأن العصمة للأنبياء والرسل فقط، لكن ربنا حافظ لأعراض الأنبياء، فيحفظ نساءهم من الوقوع في الفاحشة لأن الزنا عار\nوكمان ربنا حفظ عرض رسول الله ﷺ من إن حد يتزوج زوجاته من بعده، فإزاي مش هيحفظهن من الوقوع في الفاحشة، \nلكن رسول الله ﷺ مينفعش يحكم لنفسه، وكمان هو عارف إنه حكمه فقط لا يكفي في قطع الكلام المنتشر ومحدش هيسمع له، \nولو حد سمع هيبقى لسه النفوس برده فيها شيء، عشان كده كان مستني الوحي عشان يقفل المسألة خالص \nالمهم لما رسول الله ﷺ أنهى كلامه، السيدة عائشة دموعها وقفت، زي ما تقولوا اتصدمت إن رسول الله ﷺ مدافعش عنها وجزم ببراءتها وسارع في تكذيب الناس إللي اتكلمت،\nفقالت لأبوها أبي بكر الصديق رضي الله عنه:\nرد على رسول الله ﷺ بدالي\nفقال لها أبوها :\nوالله مش عارف أقول إيه لرسول الله ﷺ \nفقالت عائشة لأمها : ردي على رسول الله ﷺ في إللي قاله\nفقالت لها أمها : والله ما عارفة أقول إيه لرسول الله ﷺ \nهنا كل أسباب التعلق بأهل الأرض جميعا انقطعت، لا أب ولا أم ولا زوج، مفيش حد يدافع ولا يقف جنبها ويواسيها،\n☆خدوها قاعدة يا جماعة، أول ما الإنسان ينقطع من قلبه التعلق بالمخلوقين ويبقى مفيش في قلبه غير ربنا فقط يأتي الفرج على طول زي ما هنشوف\nقالت لهم السيدة عائشة:\nأنا عارفة إنكم سمعتم الكلام لحد ما استقر في نفوسكم إنه صحيح وصدقتوه، ولو قلت لكم إني بريئة وربنا عالم إني بريئة مش هتصدقوني،\nولو اعترفت لكم إني عملت حاجة والله يعلم إني بريئة هتصدقوني، فوالله لا أجدُ لي ولكم مثلا إلا كما قال أبو يوسف: \n\"فَصَبْرٌ جَمِيلٌ ۖ وَاللَّهُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ \"\nبعد ما قالت الكلام ده أعطتهم ظهرها ونامت على سريرها،\nهي عارفة إنها بريئة وإن ربنا هيبرأها، فكانت تتمنى إن رسول الله ﷺ يشوف رؤيا فيها براءتها، لأن رؤيا الأنبياء حق،\nومتخيلتش مثلا إن ربنا ممكن ينزل آيات في براءتها، هي كانت شايفة نفسها إنها أقل من إن ربنا ينزل فيها آيات تُتلى على الناس،\nوفي وسط الصمت الرهيب ده نزل الوحي على رسول الله ﷺ ببراءة السيدة عائشة، فضحك رسول الله ﷺ وقال:\nِيا عائشة ربنا برّأك\nفقالت لها أمها : قومي إلى رسول الله ﷺ واشكريه\nفقالت لها عائشة:\nوالله لا أقوم إليه، فإني لا أحمد إلا الله عز وجل\n☆هي غضبانة من رسول الله ﷺ لأنه مدافعش عنها على طول وانتظر الوحي لحد ما يثبت براءتها، يعني من باب الدلال \nقرأ رسول الله ﷺ الآيات إللي نزلت من سورة النور:\n\"إِنَّ الَّذِينَ جَاءُوا بِالْإِفْكِ عُصْبَةٌ مِّنكُمْ ۚ لَا تَحْسَبُوهُ شَرًّا لَّكُم ۖ بَلْ هُوَ خَيْرٌ لَّكُمْ ۚ لِكُلِّ امْرِئٍ مِّنْهُم مَّا اكْتَسَبَ مِنَ الْإِثْمِ ۚ وَالَّذِي تَوَلَّىٰ كِبْرَهُ مِنْهُمْ لَهُ عَذَابٌ عَظِيمٌ\"\nيعني ربنا بيقول للمؤمنين إن إللي اتقال على عائشة رضي الله عنها كذب وبهتان، وإللي قال الكذب والبهتان ده هم مجموعة منكم، \nومن المجموعة دي حسان بن ثابت شاعر النبي ﷺ، ومِسطح بن أبي مِسطح، وحَمْنة بنت جحش،\nلكل واحد منهم نصيبه من الإثم،\nوربنا بيواسي المؤمنين في الأزمة دي زي ما واساهم بعد أحداث غزوة أحد وقال لهم :\nمتفكروش إن الكذب والبهتان والأزمة إللي حصلت دي كانت شر لكم، ده خير لكم،\nأما بقى إللي بدأ الكذب والبهتان ده وأشاعه إللي هو عبد الله بن أبي بن سلول فله عذاب عظيم\n☆طيب إزاي يعني فتنة زي دي يكون فيها خير لرسول الله ﷺ والصحابة وللسيدة عائشة\nده إللي هنعرفه الجزء الجاي إن شاء الله مع تفسير باقي  الآيات من سورة النور"}]);
